"""Networking round three: new lessons 541-548.

Writes scripts/authored/fund-networking-extra.json. Run from anywhere:
    python3 scripts/authoring/more3/net.py
Numbers in worked examples are derived in the text; anything not taken from an RFC or official doc is labelled illustrative.
"""
import json, os, sys
sys.path.insert(0, os.path.join(os.path.dirname(__file__), '..', 'more2'))
from common import mc, order, est, text, diagram, flash, src, see, topic, deep  # noqa: E402


def worked(tid, n, title, body, teaches, steps, note):
    """Diagram card that walks through numbers and ends with a 'Result.' note."""
    return {"id": f"t{tid}-c{n}", "kind": "diagram", "title": title, "body": body, "teaches": teaches,
            "steps": steps, "note": note}


def predict(title, prompt, choices, correct, reveal, setup=None, kind='predict'):
    out = {"kind": kind, "title": title, "prompt": prompt}
    if setup:
        out["setup"] = setup
    out.update({"choices": [{"id": i, "label": l, "feedback": f} for i, l, f in choices],
                "correctId": correct, "reveal": reveal})
    return out


R = 'f3-networking'
T = []

# ---------------------------------------------------------------- 541 BGP and anycast
T.append(topic(541, 'bgp-and-anycast', R, 15, 'BGP and Anycast: Reaching the Nearest Edge',
 ['Explain how networks announce address blocks to each other with BGP',
  'Explain how anycast sends each user to a site that announces the same prefix',
  'Choose between anycast and DNS-based steering for failover and long connections'],
 3, 12, [244],
 [text(541, 1, 'Networks of networks agree on routes',
   'The internet is tens of thousands of independently run networks called autonomous systems (ASes), each with a number. With BGP (Border Gateway Protocol) an AS announces the address blocks it can deliver to, and each neighbour passes the announcement on, adding its own number to the AS path. A router keeps one best path per prefix, chosen first by local policy (customers before peers before paid transit) and then, among equals, by the shorter AS path. Shorter means fewer networks, not fewer kilometres or milliseconds.',
   ['bgp']),
  diagram(541, 2, 'One address announced from many cities',
   'Anycast is ordinary BGP with the same prefix announced from several places.', ['anycast', 'anycast-failover'],
   ['Sites in Mumbai, Singapore and Frankfurt all announce 192.0.2.0/24',
    'Each network between a user and the sites picks its own best path to that prefix',
    'A user in Pune usually lands in Mumbai because that path wins in their ISP',
    'If Mumbai stops announcing, routers fall back to the next-best path, perhaps Singapore',
    'Nothing on the client changes: the address stays the same, only the route moves']),
  worked(541, 3, 'Worked example: nearest by routing, not by map',
   'Anycast picks the best BGP path, which can be a farther site.', ['bgp', 'anycast'],
   ['Assume: a Mumbai user’s ISP reaches the Mumbai site through two transit networks (AS path length 3)',
    'The same ISP peers directly with the operator in Singapore (AS path length 1)',
    'BGP prefers the length-1 path, so the user is served from Singapore',
    'Mumbai to Singapore is about 3,900 km; light in fibre covers about 200 km per ms',
    'Round-trip floor: 2 × 3,900 ÷ 200 = 39 ms, against a few ms to the Mumbai site'],
   'Result. Under these illustrative assumptions the user pays at least 39 ms per round trip for a site that is not the closest. Operators fix this with peering in more places and with route policy, and they measure real latency per network rather than trusting the map.'),
  text(541, 4, 'Anycast or DNS steering',
   'DNS steering (GeoDNS) answers each resolver with a different address. It can weigh sites by load and aim precisely, but it sees the resolver rather than the user, and cached answers delay failover until the TTL runs out. Anycast reacts in the routing layer with no client cache to wait for, but control is coarse: an operator can only nudge routes, for example by prepending its own AS number several times so a path looks longer. Large services often use both.',
   ['anycast', 'as-path-prepending']),
  text(541, 5, 'Trap: assuming the route never moves mid-connection',
   'Routes change when a link fails, an ISP changes policy or a site withdraws. Packets of an open TCP connection can then reach a different site that holds no state for it, and that site answers with a reset. Short UDP exchanges such as DNS queries are ideal for anycast; long TCP sessions work in practice because routes are mostly stable, but clients must reconnect cleanly when one breaks.',
   ['anycast-failover']),
  text(541, 6, 'ECMP spreads flows inside a site',
   'Within one anycast site, a router often has several equal-cost next hops: one per server or load balancer. Equal-cost multipath (ECMP) hashes each packet’s five-tuple (addresses, ports, protocol) to pick one, so every packet of a flow reaches the same machine. Adding or removing a server changes the hash for some flows, which is why sites drain servers before removal or use consistent hashing in the balancers behind the router.',
   ['ecmp'])],
 [mc('t541-a1', 'bgp', 'Two paths to the same prefix tie on local policy. Which one does a BGP router usually prefer next?',
   [('a', 'The path through fewer autonomous systems'), ('b', 'The path with the lower measured round-trip time'), ('c', 'The path with more total link bandwidth'), ('d', 'The path it learned most recently')], 'a',
   'After policy, a shorter AS path wins. BGP does not measure round-trip time or bandwidth, so b and c are not inputs to its choice; and later tie-breakers tend to favour the older, more stable path, not the newest.'),
  mc('t541-a2', 'anycast', 'Several sites announce 192.0.2.0/24. What decides which site a given user reaches?',
   [('a', 'The lowest current CPU load among the sites'), ('b', 'The route choices of networks between the user and the sites'), ('c', 'The location of the user’s DNS resolver'), ('d', 'A geographic distance the routers compute from the user’s IP address')], 'b',
   'Each network on the way picks its best BGP path. Routers do not see server load; resolver location matters for GeoDNS, not anycast; and no router computes geographic distance.'),
  mc('t541-a3', 'anycast-failover', 'The Mumbai site fails and withdraws its announcement. What happens to users who were reaching it?',
   [('a', 'Their routers converge on the next-best announcement, often a farther site'), ('b', 'They keep failing until their resolver’s cached DNS answer for the service expires'), ('c', 'Their clients pick another address from the DNS answer'), ('d', 'Their packets queue at Mumbai until the site restarts')], 'a',
   'The address is unchanged, so only routing moves. DNS caches are not involved, which is the point of anycast; with one anycast address there is no other address to try; and routers forward rather than hold packets for a dead site.'),
  mc('t541-a4', 'anycast-failover', 'Which workload suits plain anycast with no extra handling?',
   [('a', 'Hour-long uploads over one TCP connection'), ('b', 'A game session held in one server’s memory'), ('c', 'A DNS service answering short UDP queries'), ('d', 'Sending each user to the shard with their data')], 'c',
   'A query and its answer finish before a route can move. Long uploads and in-memory sessions break if the route shifts; and anycast picks a site by routing, not by where a user’s data lives.'),
  mc('t541-a5', 'ecmp', 'A router spreads an anycast prefix over eight servers by hashing the five-tuple. Why hash instead of rotating packet by packet?',
   [('a', 'Hashing gives each server exactly the same load'), ('b', 'Every packet of a connection reaches the server holding its state'), ('c', 'Routers cannot forward a single prefix to more than one next hop at a time'), ('d', 'Hashing hides the client address from the servers')], 'b',
   'Per-flow hashing keeps a TCP connection on one machine. Load is only roughly even, since flows differ in size; routers can forward to several next hops (that is ECMP); and the client address is still visible.'),
  order('t541-a6', 'anycast-failover', 'Order what happens when an anycast site fails.',
   ['The site’s health check fails', 'The site withdraws its route announcement', 'Neighbouring networks propagate the withdrawal', 'Routers select their next-best path', 'New packets arrive at another site'],
   ['s4', 's2', 's5', 's1', 's3'], 'Detection, withdrawal, propagation, a new best path, then traffic moves. Connections open at the failed site must reconnect.'),
  est('t541-a7', 'anycast', 'A user is routed to a site 3,900 km away. If light in fibre covers 200 km per ms, what is the round-trip floor in ms?', 'ms', 39,
   ['Straight-line fibre with no queueing or detours', 'Round trip means there and back'],
   '2 × 3,900 ÷ 200', '7,800 km ÷ 200 km/ms = 39 ms',
   'Sanity check: real paths are longer than great circles and add router queues, so measured RTT is usually well above this floor; a nearby site would be a few ms.', 0.1, [19.5, 78])],
 flash(541, [('BGP picks a path by?', 'Local policy first, then the shorter AS path; it does not measure latency.'),
             ('Anycast?', 'The same prefix announced from several sites; routing delivers each user to one of them.'),
             ('Anycast failover?', 'The failing site withdraws its route; routers move to the next-best path with no DNS cache to wait for.')]),
 src([('RFC 4271: A Border Gateway Protocol 4 (BGP-4)', 'https://www.rfc-editor.org/rfc/rfc4271'),
      ('RFC 4786: Operation of Anycast Services', 'https://www.rfc-editor.org/rfc/rfc4786'),
      ('RFC 7094: Architectural Considerations of IP Anycast', 'https://www.rfc-editor.org/rfc/rfc7094')]),
 deep(['bgp', 'anycast', 'anycast-failover'], 'How a route reaches every network',
  ['An autonomous system originates a prefix, such as 192.0.2.0/24, by announcing it to its BGP neighbours over long-lived TCP sessions. The announcement carries the AS path, the list of networks it has crossed, which lets routers reject loops and compare paths. Many networks refuse IPv4 prefixes more specific than a /24, so that is the smallest block worth announcing from a site.',
   'Each router that hears several paths to the same prefix chooses one. Business policy comes first: a network prefers routes learned from paying customers, then from settlement-free peers, then from transit providers it pays. Only when policy ties does the shorter AS path win, followed by further tie-breakers. The chosen path is passed on to neighbours, subject to export policy.',
   'Anycast means several sites originate the same prefix. Every network independently picks one of those announcements, so users are divided among sites by the shape of the internet’s business relationships. In well-peered regions that usually means a nearby site; in poorly connected ones it can mean a distant site, as the Mumbai and Singapore example shows.',
   'When a site fails, its routers stop announcing the prefix, ideally triggered by a health check rather than by the routers dying. The withdrawal spreads hop by hop and each network falls back to its next-best path. Convergence typically takes seconds and can take longer for some networks, but no client cache is involved, unlike DNS failover, which waits out TTLs in resolvers.',
   'Inside a site, routers spread flows with ECMP hashing so that one connection stays on one server. Operators tune which site serves whom by announcing more specific prefixes from some sites, prepending their AS number to make a path look longer, or tagging routes with communities that ask neighbours to change preference. All of these are coarse, so precise load steering is usually done by DNS or by layer 7 balancers on top.'],
  ['DNS servers, CDN edges and DDoS absorption, where many sites should share one address.', 'Failover that must not wait for DNS caches to expire.'],
  ['Avoid relying on anycast alone to pin long stateful sessions to one site.', 'Avoid it when traffic must be split by exact percentages or by where a user’s data lives.'],
  ['Approach', 'Failover speed', 'Steering precision', 'Fits'],
  [['Anycast', 'Routing convergence, no client cache', 'Coarse: prepends, more-specifics', 'DNS, CDN edges, DDoS absorption'],
   ['DNS steering', 'Bounded by TTL and resolver caching', 'Fine: per resolver, by load', 'Region choice, weighted rollouts'],
   ['Both together', 'Fast in the edge, precise per region', 'Fine at the region level', 'Large global services']],
  'A user sent to the wrong site',
  ['Mumbai site reached through two transit networks (AS path length 3)', 'Singapore site reached through a direct peering (AS path length 1)', 'About 3,900 km Mumbai to Singapore; about 200 km per ms in fibre'],
  ['BGP compares AS paths after policy: 1 beats 3, so Singapore wins.',
   'One-way fibre floor: 3,900 ÷ 200 = 19.5 ms.',
   'Round-trip floor: 2 × 19.5 = 39 ms, before detours and queueing.',
   'Each request needing three round trips (TCP, TLS, request) waits at least 117 ms instead of a few ms.'],
  'Anycast followed routing, not geography; better peering near Mumbai would bring the user back to the local site.',
  'Anycast operation in RFC 4786 and RFC 7094', 'Official documentation',
  'RFC 4786 (Operation of Anycast Services, BCP 126) describes how operators announce one prefix from many sites, tie announcements to service health so a broken node withdraws its route, and accept that a route change can move a stateful session to another node. RFC 7094 discusses the architecture, noting that anycast suits short transactions such as DNS best and that longer TCP sessions depend on route stability. The DNS root servers are a well-known public example: a small set of addresses served from many sites worldwide.',
  [('“Anycast sends every user to the geographically closest site.”', '“Anycast sends users along their networks’ best BGP paths, which are usually nearby but depend on peering.”'),
   ('“We can shift exactly 30% of Mumbai traffic with anycast.”', '“Anycast steering is coarse; for exact splits I’d use DNS weights or a layer 7 balancer.”')],
  ['BGP picks paths by policy first, then by the shorter AS path, never by measured latency.', 'Anycast announces one prefix from many sites; routing chooses the site.', 'Anycast failover is a route withdrawal, with no DNS cache to wait for.', 'ECMP hashing keeps each flow on one server inside a site.']),
 predict('Shift load away from a hot site',
  'Your anycast site in Mumbai is healthy but running hot, and you cannot add servers this week. You want some of its users to land in Singapore instead. What do you do?',
  [('a', 'Prepend your AS number on Mumbai’s announcements', 'Right: networks that compare path length see Mumbai as farther and some move to Singapore. It is coarse; networks whose policy decides earlier ignore it.'),
   ('b', 'Lower the TTL on the DNS record for the service', 'The service has one anycast address, so every DNS answer is the same; the TTL changes nothing about which site serves it.'),
   ('c', 'Withdraw the Mumbai announcement entirely', 'That moves every Mumbai user, not some, and may overload Singapore in turn. Keep withdrawal for real failures.')],
  'a', 'Anycast traffic engineering works by making routes more or less attractive: AS-path prepending, more-specific prefixes or BGP communities. You cannot choose an exact fraction, which is why large services pair anycast with DNS or layer 7 steering for precise control.'),
 see([(6, 'DNS steering is the other way to send users to a region'), (19, 'CDN edges are the most common anycast deployment'), (244, 'Routing tables and longest-prefix match underlie every BGP decision')])))

# ---------------------------------------------------------------- 542 keep-alive, pools, idle timeouts
T.append(topic(542, 'keep-alive-pools-and-idle-timeouts', R, 16, 'Keep-Alive, Connection Pools and Idle Timeouts',
 ['Explain why reusing connections saves round trips and server work',
  'Order idle timeouts across client, load balancer and server to avoid reset races',
  'Spot load imbalance caused by long-lived HTTP/2 connections'],
 2, 12, [247, 250],
 [text(542, 1, 'One connection, many requests',
   'HTTP/1.1 connections are persistent by default: after a response, the client may send the next request on the same connection. HTTP/2 goes further and multiplexes many requests at once on one connection. Reuse skips the TCP and TLS handshakes, the slow-start ramp and the server’s key-exchange work. Every hop also runs an idle timer, and whichever side times out first closes the connection.',
   ['persistent-connections']),
  worked(542, 2, 'Worked example: what a cold connection costs between regions',
   'Count round trips before the first response byte.', ['persistent-connections'],
   ['Assume: a service calls a dependency in another region with a 60 ms round trip, over TLS 1.3',
    'Cold: TCP handshake 1 RTT + TLS 1 RTT + request and response 1 RTT = 3 × 60 = 180 ms',
    'Warm (reused connection): request and response only = 60 ms',
    'At 200 calls per second with no reuse, the dependency also runs 200 TLS key exchanges per second'],
   'Result. Reuse cuts each call from 180 ms to 60 ms in this illustrative case and removes the handshake CPU. Inside one data centre the round trips are sub-millisecond, so there the CPU and port savings matter more than the latency.'),
  diagram(542, 3, 'The idle-timeout race behind rare 502s',
   'A load balancer reuses a connection that the backend is closing at that same moment.', ['idle-timeout-race'],
   ['The balancer keeps idle connections to the backend for up to 60 s',
    'The backend closes idle keep-alive connections after 5 s and sends a FIN',
    'Before the FIN arrives, the balancer sends a new request on that connection',
    'The backend’s socket is closed, so its kernel answers with a reset',
    'The balancer has no response to forward and returns 502 to the client']),
  text(542, 4, 'Order the timers from the outside in',
   'Each caller’s idle timeout should be shorter than its callee’s: client pool shorter than the balancer, balancer shorter than the backend. Then the side that sends requests is the one that closes idle connections, and it never sends on a connection the other end is closing. AWS documents this for its Application Load Balancer, recommending an application keep-alive timeout larger than the balancer’s idle timeout. If a reused connection still fails before any response, a client may retry automatically only if the request is idempotent, such as GET, PUT or DELETE.',
   ['timeout-ordering', 'safe-retry']),
  text(542, 5, 'Trap: long-lived connections pin load to old servers',
   'HTTP/2, gRPC and WebSocket clients hold a few connections for a long time. Behind a layer 4 balancer, which balances per connection, scaling from 4 to 8 servers leaves the new 4 nearly idle until connections recycle. Balance per request at layer 7, or cap connection age so servers send an HTTP/2 GOAWAY frame and clients reconnect gradually, landing on the new servers.',
   ['long-lived-imbalance']),
  text(542, 6, 'Sizing a pool with Little’s law',
   'Connections in use equal request rate times how long each request holds one. At 2,000 requests per second and 25 ms per request, about 2,000 × 0.025 = 50 HTTP/1.1 connections are busy on average, so a pool of 50 with headroom for bursts works. If latency doubles, the need doubles. HTTP/2 carries many streams per connection, up to the server’s advertised limit; RFC 9113 recommends allowing at least 100 concurrent streams.',
   ['pool-sizing'])],
 [mc('t542-a1', 'idle-timeout-race', 'A balancer has a 60 s idle timeout and its backends close idle connections after 5 s. Users see rare 502s, mostly at low traffic. What is the likely cause?',
   [('a', 'The balancer runs out of source ports when traffic is light'), ('b', 'TLS session tickets on the backend expire every 5 seconds'), ('c', 'A backend closes a connection just as the balancer reuses it'), ('d', 'The backend’s listen queue overflows while it is idle')], 'c',
   'Low traffic leaves connections idle long enough for the backend’s 5 s timer to fire, and the balancer can send a request into the closing socket. Light traffic does not exhaust ports; ticket expiry forces a full handshake, not a 502; and an idle listen queue is empty.'),
  mc('t542-a2', 'timeout-ordering', 'Which ordering of idle timeouts avoids that race?',
   [('a', 'Client pool < balancer < backend keep-alive'), ('b', 'Backend keep-alive < balancer < client pool'), ('c', 'All three set to the same value'), ('d', 'A long balancer timeout with short client ones')], 'a',
   'The caller should close first at every hop. Reversing the order makes the race the norm; equal values still race when both timers fire together; and a long balancer timeout says nothing about the backend’s, which is where the race happens.'),
  mc('t542-a3', 'persistent-connections', 'Why does connection reuse save more latency between regions than inside one data centre?',
   [('a', 'Handshakes cost round trips, and those are long between regions'), ('b', 'Cross-region links do not allow TLS session resumption or tickets'), ('c', 'Services in one data centre share a single TCP connection'), ('d', 'Inside a data centre, a handshake sends no packets')], 'a',
   'Each saved round trip is worth tens of ms between regions and well under one ms locally. Resumption works on any link; services do not share one connection; and a local handshake still sends packets, just quickly.'),
  mc('t542-a4', 'long-lived-imbalance', 'A gRPC service scales from 4 to 8 pods behind a layer 4 balancer, yet the new pods stay nearly idle. Why?',
   [('a', 'New pods must load their TLS certificates for an hour first'), ('b', 'Clients keep their HTTP/2 connections, so requests stay on old pods'), ('c', 'A layer 4 balancer sends only UDP traffic to new pods'), ('d', 'gRPC limits each client to the set of pods that it resolved at startup')], 'b',
   'Balancing happened when the connections opened, and they are long-lived. Certificates load in seconds; a layer 4 balancer forwards TCP as well; and gRPC clients can discover new backends, but a single long connection still pins traffic.'),
  mc('t542-a5', 'safe-retry', 'A reused connection is reset before any response arrives. Which request can the client retry automatically?',
   [('a', 'POST /payments with no idempotency key'), ('b', 'PATCH /cart that adds one to a quantity'), ('c', 'POST /orders that creates a new order'), ('d', 'GET /orders/42 that reads one order')], 'd',
   'GET is idempotent, so a repeat cannot double an effect. The server may have processed the others before the reset, so retrying them could charge, add or create twice unless they carry an idempotency key.'),
  order('t542-a6', 'idle-timeout-race', 'Order the events in the idle-timeout race.',
   ['The backend’s idle timer fires', 'The backend sends a FIN and closes its socket', 'The balancer sends a request before the FIN arrives', 'The backend’s kernel answers with a reset', 'The balancer returns 502 to the client'],
   ['s3', 's5', 's1', 's4', 's2'], 'The backend closes first, the balancer sends into the gap, and the reset becomes a 502. Making the backend’s timer longer than the balancer’s removes the first step.'),
  est('t542-a7', 'pool-sizing', 'An API gateway forwards 2,000 calls per second upstream, and each upstream call occupies its own HTTP/1.1 connection for 25 ms. What pool size matches the mean concurrency?', 'connections', 50,
   ['Calls are spread evenly', 'One request per HTTP/1.1 connection at a time'],
   '2,000 × 0.025 s', '2,000 × 0.025 = 50 connections',
   'Design implication: size the pool above 50 with headroom, and watch latency; at 100 ms per call the same rate needs 200 connections.', 0.1, [500, 5, 80])],
 flash(542, [('Idle timeout order?', 'Client pool < load balancer < backend keep-alive, so the caller always closes first.'),
             ('Rare 502s at low traffic?', 'Often the backend closing idle connections before the balancer does.'),
             ('Busy connections?', 'Request rate × time each request holds a connection (Little’s law).')]),
 src([('RFC 9112: HTTP/1.1, section 9 Connection Management', 'https://www.rfc-editor.org/rfc/rfc9112#section-9'),
      ('RFC 9113: HTTP/2', 'https://www.rfc-editor.org/rfc/rfc9113'),
      ('AWS: Application Load Balancer connection idle timeout', 'https://docs.aws.amazon.com/elasticloadbalancing/latest/application/edit-load-balancer-attributes.html#connection-idle-timeout')]),
 deep(['persistent-connections', 'idle-timeout-race', 'timeout-ordering'], 'How a pooled connection lives and dies',
  ['A client opens a connection with a TCP handshake and, for HTTPS, a TLS handshake. Once the first response is read, the connection goes back to a pool. HTTP/1.1 treats connections as persistent unless a side sends Connection: close, so the next request to the same host can reuse it immediately with no setup round trips and no new key exchange.',
   'Each side keeps idle connections only for a while, because each costs memory, a file descriptor and, on a balancer, a slot in its connection table. Clients have a pool idle timeout, balancers an idle timeout, and servers a keep-alive timeout. When one expires, that side closes the connection with a FIN. These timers are independent and each defaults to whatever the software chose.',
   'Closing is not instant for the other side. The FIN takes time to arrive, and until it does the peer believes the connection is usable. If the peer sends a request in that window, it reaches a closed socket and the kernel answers with a reset. A balancer then has nothing to forward and returns 502; a client library reports a reset or an unexpected end of stream.',
   'The fix is to make the side that sends requests close first. Set the client pool’s idle timeout below the balancer’s, and the balancer’s below the backend’s keep-alive timeout, with a few seconds of margin at each step. Clients should also retry idempotent requests once when a reused connection fails before any response, which RFC 9112 permits.',
   'Long-lived connections create a different problem. A layer 4 balancer chooses a backend once per connection, so multiplexed HTTP/2 or gRPC traffic stays where the connection landed. New servers added by autoscaling see little traffic. Layer 7 balancing spreads individual requests; alternatively, servers cap connection age and send GOAWAY, which tells clients to finish in-flight streams and reconnect.'],
  ['Any service calling another over HTTP many times per second.', 'Paths with a high round-trip time, such as cross-region calls.'],
  ['Avoid very long idle timeouts on servers with few file descriptors or memory per connection.', 'Avoid relying on a layer 4 balancer to spread long-lived HTTP/2 or WebSocket traffic.'],
  ['Hop', 'Timer', 'Rule of thumb'],
  [['Client pool', 'Pool idle timeout', 'Shortest of the three'],
   ['Load balancer', 'Idle timeout', 'Longer than the client, shorter than the backend'],
   ['Backend server', 'Keep-alive timeout', 'Longest, a few seconds above the balancer']],
  'Cold versus warm calls across regions',
  ['60 ms round trip, TLS 1.3 over TCP', '200 calls per second, 25 ms of server time per call'],
  ['Cold call: 3 round trips (TCP, TLS, request) = 180 ms, plus 25 ms of work = 205 ms.',
   'Warm call: 1 round trip = 60 ms, plus 25 ms of work = 85 ms.',
   'Busy connections when warm: 200 × 0.085 s = 17 on average.',
   'Without reuse: 200 new connections and 200 key exchanges per second, each port then held in TIME_WAIT.'],
  'Reuse cuts latency by more than half here and turns hundreds of handshakes per second into a pool of about 17 connections.',
  'Persistent connections in RFC 9112 and AWS load balancer guidance', 'Official documentation',
  'RFC 9112 section 9.3 makes HTTP/1.1 connections persistent by default and explains that a client may retry an idempotent request automatically when a persistent connection closes before the response arrives, but must not do so for non-idempotent requests without knowing they are safe. AWS documentation for the Application Load Balancer describes its configurable idle timeout and recommends enabling keep-alive on targets with a keep-alive timeout greater than the load balancer’s idle timeout.',
  [('“The 502s are random network blips.”', '“Rare 502s at low traffic usually mean the backend closes idle connections before the balancer; I’d make its keep-alive longer than the balancer’s timeout.”'),
   ('“We added pods, so load is spread.”', '“With long-lived HTTP/2 connections behind a layer 4 balancer, new pods stay idle until connections recycle.”')],
  ['Reusing a connection skips TCP and TLS setup and key-exchange work.', 'Order idle timeouts so the caller closes first: client < balancer < backend.', 'Retry automatically only idempotent requests after a reused connection fails.', 'Long-lived HTTP/2 connections need layer 7 balancing or a maximum age.']),
 {"kind": "slider", "title": "What a cold connection costs",
  "prompt": "A cold HTTPS call needs three round trips before the first response byte: TCP, TLS 1.3 and the request. Slide the round-trip time and find where cold calls blow a 200 ms budget.",
  "model": "rtt-handshake", "params": {"roundTrips": 3, "budgetMs": 200},
  "control": {"label": "Round-trip time", "min": 1, "max": 150, "step": 1, "initial": 60, "unit": "ms"},
  "takeaway": "Above about 66 ms of round trip, three round trips no longer fit in 200 ms. A reused connection needs only one, so between regions reuse is the difference between meeting the budget and missing it."},
 see([(274, 'Database connection pools follow the same sizing and idle-timeout rules'), (12, 'Layer 4 versus layer 7 balancing decides how long-lived connections spread'), (249, 'Every new connection uses an ephemeral port that then waits in TIME_WAIT')])))

# ---------------------------------------------------------------- 543 debugging connections
T.append(topic(543, 'debugging-network-connections', R, 17, 'Debugging a Connection: Refused, Timeout or Reset',
 ['Read what refused, timed out and reset connections each say about the path',
  'Walk a failing request up the layers from name to HTTP',
  'Use traceroute, timing breakdowns and packet captures without misreading them'],
 2, 12, [246, 247],
 [text(543, 1, 'Each failure leaves a different signature',
   'Connection refused means the host answered with a TCP reset: it is reachable, but nothing listens on that port, or a firewall rejects actively. A timeout means no answer at all: a firewall or security group drops packets, a route is wrong or the host is down. A reset on an open connection means the peer or a middlebox killed it, often an idle timeout or a crashed process. For names, NXDOMAIN says the name does not exist, while SERVFAIL says the resolver could not get an answer.',
   ['failure-signatures']),
  diagram(543, 2, 'Walk up the layers, one question each',
   'Answer each question before moving up; most outages stop at one layer.', ['layered-debugging'],
   ['Name: does it resolve to the address you expect, from the same resolver the client uses?',
    'Route: are packets reaching that address? Traceroute shows where replies stop',
    'Port: does a TCP handshake complete, and is the failure refused or a timeout?',
    'TLS: does the handshake finish, and does the certificate match the name?',
    'HTTP: which status came back, and from which hop: proxy, balancer or the app?']),
  worked(543, 3, 'Worked example: reading a 3-second connect',
   'A timing breakdown splits a request into DNS, connect, TLS and first byte.', ['timing-phases'],
   ['Measured: DNS 4 ms, TCP connect done at 3,010 ms, RTT to the host about 6 ms',
    'Connect phase: 3,010 − 4 = 3,006 ms, against one 6 ms round trip expected',
    'TCP waits 1 s before resending a lost SYN, then doubles: 1 s, then 2 s more',
    '1 s + 2 s + 6 ms ≈ 3,006 ms: the first two SYNs were lost and the third got through'],
   'Result. Connect times clustering near 1, 3 or 7 seconds point to dropped SYNs, from a full accept queue, a firewall or a lossy path, not to slow application code. Linux gives up after about 127 seconds of such retries by default.'),
  text(543, 4, 'traceroute works by expiring packets',
   'Traceroute sends probes with TTL 1, then 2, then 3. Each router that decrements a TTL to zero drops the probe and returns an ICMP Time Exceeded message, revealing its address and the round trip to it. Ping uses ICMP Echo, which many hosts and clouds block, so a failed ping alone does not mean a host is down; a TCP connect to the real port is the better test.',
   ['traceroute-ttl']),
  text(543, 5, 'Trap: reading a silent traceroute hop as the outage',
   'A row of asterisks means that router did not answer the probe; many routers rate-limit or ignore ICMP while forwarding traffic normally. If later hops and the destination reply, the silent hop is fine. Only when every hop after some point is silent has the path stopped there. Likewise, high latency at one middle hop that does not carry on to later hops is that router’s slow reply, not added delay.',
   ['traceroute-ttl']),
  text(543, 6, 'When to capture packets',
   'A packet capture on both ends settles arguments. If the client’s SYN leaves but never reaches the server, something on the path drops it. If the server answers with SYN-ACK that never returns, suspect an asymmetric route or a return-path firewall. If a reset appears, the capture shows who sent it. Filter captures to the one connection, and treat them as sensitive, since they can hold credentials and personal data.',
   ['packet-capture'])],
 [mc('t543-a1', 'failure-signatures', 'Connecting to 10.0.3.7 on port 5432 fails at once with “connection refused”. What does that say?',
   [('a', 'A firewall silently dropped the SYN'), ('b', 'The host replied, but nothing accepted that port'), ('c', 'The name did not resolve to any address'), ('d', 'The server’s certificate did not match')], 'b',
   'Refused is an immediate reset from the host. A silent drop would time out instead; a name failure happens before any connection to 10.0.3.7; and certificates are checked only after TCP succeeds.'),
  mc('t543-a2', 'failure-signatures', 'The same connect now hangs for about two minutes before timing out. What is the most likely cause?',
   [('a', 'The database process has stopped on a reachable host'), ('b', 'The database rejected the client’s password'), ('c', 'A security group or firewall drops the packets'), ('d', 'The server’s TLS certificate has expired')], 'c',
   'No reply at all means packets are dropped. A stopped process on a reachable host gives refused; a bad password and an expired certificate both need a completed TCP handshake first, and fail with a clear error.'),
  mc('t543-a3', 'traceroute-ttl', 'How does traceroute discover the routers along a path?',
   [('a', 'It asks each router for its BGP routing table'), ('b', 'It reads the list of routers published in DNS'), ('c', 'It divides one ping’s total round-trip time by the number of hops'), ('d', 'It sends probes with rising TTL and reads Time Exceeded replies')], 'd',
   'Each TTL value expires one hop further, and that router reports itself. Routers do not hand out BGP tables to hosts; DNS has no router list; and hop count cannot be derived from a ping time.'),
  mc('t543-a4', 'traceroute-ttl', 'Hop 6 shows “* * *” but hops 7 to 12 answer and the destination replies. What does hop 6 tell you?',
   [('a', 'That router ignores probes but forwards traffic'), ('b', 'Packets are being lost at hop 6'), ('c', 'Hop 6 is the firewall blocking the service'), ('d', 'The path loops back at hop 6')], 'a',
   'Later hops and the destination answered, so traffic passed hop 6. Loss or a blocking firewall there would silence everything after it, and a loop shows the same addresses repeating.'),
  mc('t543-a5', 'timing-phases', 'A request’s connect phase takes about 3 seconds while the round trip is 6 ms. What is the best reading?',
   [('a', 'The server took 3 seconds to build the page'), ('b', 'Two SYNs were lost and resent after 1 s and 2 s'), ('c', 'The TLS handshake needed hundreds of round trips'), ('d', 'DNS answered slowly from a distant resolver')], 'b',
   '1 s + 2 s of retransmission backoff matches the 3 s. Page building happens after connect and TLS; TLS is a separate phase after connect; and DNS has its own, separate timing.'),
  order('t543-a6', 'layered-debugging', 'Order the checks when a request to a service fails.',
   ['Check the name resolves to the expected address', 'Check packets reach that address', 'Check the TCP handshake completes', 'Check the TLS handshake and certificate', 'Check the HTTP status and which hop sent it'],
   ['s4', 's1', 's5', 's3', 's2'], 'Each layer depends on the one below it, so a failure low down explains every symptom above it.'),
  est('t543-a7', 'timing-phases', 'A SYN is first resent after 1 s, and each later wait doubles. If the first three SYNs are lost, how many seconds after the first does the fourth go out?', 's', 7,
   ['Waits of 1 s, 2 s and 4 s between attempts', 'Round-trip time is negligible next to the waits'],
   '1 + 2 + 4', '1 + 2 + 4 = 7 s',
   'Sanity check: connect times bunched near 1, 3 and 7 seconds are a fingerprint of dropped SYNs rather than slow servers.', 0.05, [3, 4, 8])],
 flash(543, [('Refused vs timeout?', 'Refused: host replied with a reset, nothing on the port. Timeout: packets dropped, no reply.'),
             ('A silent traceroute hop?', 'That router ignores probes; it matters only if every later hop is silent too.'),
             ('Connect takes about 3 s?', 'Two lost SYNs, resent after 1 s and 2 s.')]),
 src([('RFC 792: Internet Control Message Protocol', 'https://www.rfc-editor.org/rfc/rfc792'),
      ('RFC 6298: Computing TCP’s Retransmission Timer', 'https://www.rfc-editor.org/rfc/rfc6298'),
      ('man7: tcp(7)', 'https://man7.org/linux/man-pages/man7/tcp.7.html')]),
 deep(['failure-signatures', 'layered-debugging', 'timing-phases'], 'What each layer reports when it fails',
  ['Name resolution fails before any connection exists. Query the same resolver the client uses, then the authoritative servers directly, and compare: a stale cached answer, a split-horizon record that differs inside and outside a network, or an NXDOMAIN from a typo each look different. SERVFAIL points at the resolver’s path to the authoritative servers, or at a failed DNSSEC validation.',
   'At the network layer, a router that has no route, or a host that is administratively unreachable, may return an ICMP Destination Unreachable, which applications report as “no route to host” or “network unreachable”. More often, filters drop packets silently. Traceroute uses expiring TTLs to show how far probes get, keeping in mind that routers may ignore probes while forwarding traffic.',
   'At the transport layer, the TCP handshake gives three outcomes. A SYN-ACK means the port is open. A reset means the host is up but refused, usually because nothing listens. Silence means a drop somewhere, and the client keeps resending the SYN with exponentially growing waits, starting from a 1 s initial retransmission timeout as RFC 6298 recommends, until it gives up.',
   'Above TCP, TLS failures name their cause: an unknown certificate authority, a name mismatch, an expired certificate or no shared protocol version. HTTP failures need the source identified: a 502 or 504 from a proxy or balancer means the hop behind it failed or was slow, while a 500 from the application is its own error. Response headers and access logs at each hop show who answered.',
   'Timing breakdowns tie it together. Most HTTP clients and browsers report DNS, connect, TLS, time to first byte and transfer separately. A long connect phase means network or accept-queue trouble; a long TLS phase means handshake round trips or certificate checks; a long wait for the first byte with fast setup means the server itself was slow.'],
  ['Any failing or slow request where the cause is not yet known.', 'Arguments over whether “the network” or “the app” is at fault.'],
  ['Avoid concluding a host is down from a failed ping alone.', 'Avoid treating one silent or slow middle hop in traceroute as the problem.'],
  ['Symptom', 'Usually means', 'Check next'],
  [['Connection refused', 'Host reachable, nothing on the port', 'Is the service listening on that address and port?'],
   ['Connect timeout', 'Packets dropped on the way', 'Security groups, firewalls, routes'],
   ['Reset mid-connection', 'Peer or middlebox closed it', 'Idle timeouts, crashes, proxy limits'],
   ['502 or 504 from a proxy', 'The hop behind the proxy failed or was slow', 'Upstream health and timeouts']],
  'Decoding a slow connect',
  ['DNS 4 ms, connect complete at 3,010 ms', 'Round-trip time to the server 6 ms', 'SYN retransmission waits of 1 s, then 2 s, then 4 s'],
  ['Connect phase: 3,010 − 4 = 3,006 ms.',
   'Subtract one round trip: 3,006 − 6 = 3,000 ms of waiting.',
   '3,000 ms = 1,000 ms + 2,000 ms, the first two retransmission waits.',
   'So two SYNs were lost; a third loss would have pushed connect to about 7 s.'],
  'The delay is packet loss before the connection exists, so look at accept queues, firewalls and the path, not the application.',
  'ICMP and TCP timers in the RFCs and the Linux manual', 'Official documentation',
  'RFC 792 defines the ICMP Echo, Destination Unreachable and Time Exceeded messages that ping and traceroute rely on. RFC 6298 recommends an initial TCP retransmission timeout of one second, doubling on each further loss. The Linux tcp(7) manual page documents tcp_syn_retries, whose default of 6 retries corresponds to roughly 127 seconds before a connect attempt gives up, which is why a filtered port can leave a client waiting about two minutes.',
  [('“Ping fails, so the server is down.”', '“Many hosts block ICMP; I’d try a TCP connect to the real port before deciding.”'),
   ('“Traceroute stops at hop 6, so hop 6 is broken.”', '“Hops after 6 answer, so hop 6 just ignores probes; the path is fine.”')],
  ['Refused means reachable with nothing listening; a timeout means packets are dropped.', 'Debug upward: name, route, port, TLS, then HTTP and which hop answered.', 'Connect times near 1, 3 or 7 seconds mean lost SYNs.', 'A silent traceroute hop matters only if every later hop is silent too.']),
 predict('Where do you look first?',
  'An app on host A connects to the database by IP in milliseconds. The same app on host B, in another subnet, hangs on connect until it times out. DNS is not involved. What do you check first?',
  [('a', 'The database’s password and user grants', 'Authentication happens after TCP connects, and here the connect itself never completes.'),
   ('b', 'Security group or firewall rules for B’s subnet', 'Right: a hang with no reply means packets are dropped, and the difference between A and B is their network path and rules.'),
   ('c', 'The database’s TLS certificate', 'TLS starts only after the TCP handshake, which never finishes from B.')],
  'b', 'A timeout is silence, so something drops packets. Refused would mean the host answered; an authentication or TLS error would mean TCP succeeded. Comparing a working source with a failing one narrows it to what differs: subnet, routes and filters.'),
 see([(329, 'Security groups and network ACLs are the usual cause of silent drops in a cloud network'), (6, 'How resolvers and caching behave when the name is the problem'), (239, 'Connect and request timeouts decide how long a client waits on each failure')])))

# ---------------------------------------------------------------- 544 loss, jitter, throughput
T.append(topic(544, 'packet-loss-jitter-throughput', R, 18, 'Packet Loss, Jitter and Single-Flow Throughput',
 ['Estimate how loss and round-trip time cap one TCP flow with the Mathis model',
  'Size a jitter buffer for real-time audio or video',
  'Recognise bufferbloat and why it hurts interactive traffic'],
 3, 13, [248, 253],
 [text(544, 1, 'Loss caps a TCP flow, not just slows it',
   'Loss-based congestion control shrinks the window after each loss and grows it again slowly, so the average window settles where growth and cuts balance. The Mathis model captures this: throughput ≈ (MSS ÷ RTT) × 1.22 ÷ √p, where p is the loss rate. Link speed does not appear. Doubling the round trip halves the rate, and four times the loss also halves it. Treat it as an estimate for classic loss-based TCP; delay-based algorithms such as BBR behave differently.',
   ['mathis-model', 'loss-throughput']),
  worked(544, 2, 'Worked example: one flow on a long, slightly lossy path',
   'Plug real-looking numbers into the Mathis model.', ['mathis-model'],
   ['Assume: MSS 1,460 bytes = 11,680 bits, RTT 100 ms, random loss 0.01% (p = 0.0001)',
    '√p = 0.01, and MSS ÷ RTT = 11,680 ÷ 0.1 s = 116,800 bit/s',
    'Throughput ≈ 116,800 × 1.22 ÷ 0.01 ≈ 14.2 Mbit/s',
    'Same loss at 10 ms RTT: ten times more, about 142 Mbit/s'],
   'Result. One flow on this path tops out near 14 Mbit/s even on a 10 Gbit/s link. Bulk transfers across continents therefore use several parallel flows, reduce loss, or use congestion control that does not treat every loss as congestion.'),
  text(544, 3, 'Jitter and the playout buffer',
   'Jitter is variation in delay. A real-time audio or video receiver holds packets in a jitter buffer and plays them on a steady clock, so the buffer must cover the spread of delays: if one-way delay ranges from 40 to 90 ms, about 50 ms of buffer avoids late packets, at the cost of 50 ms more latency. A packet that arrives after its playout time is as useless as a lost one, which is why media usually conceals losses instead of waiting for retransmissions.',
   ['jitter']),
  diagram(544, 4, 'How an oversized router queue becomes delay',
   'Bufferbloat: a deep queue at the bottleneck adds latency without adding throughput.', ['bufferbloat'],
   ['A bulk upload sends faster than the home uplink can carry',
    'The router’s queue fills, because loss-based TCP keeps growing until packets drop',
    'A full 1 MB queue on a 10 Mbit/s uplink holds 8,000,000 ÷ 10,000,000 = 0.8 s of data',
    'A call’s packets wait behind it, so the call lags by most of a second',
    'Active queue management, such as CoDel, drops or marks early to keep the queue short']),
  text(544, 5, 'Trap: buying bandwidth to fix a lossy path',
   'If loss comes from a flaky wireless hop or a bad interface rather than congestion, a faster link changes nothing for one flow, because the Mathis cap depends on loss and round trip, not capacity. Fix the loss, shorten the round trip with a closer endpoint, or split the transfer over several connections, each with its own cap. Also check the measurement: routers that rate-limit ICMP make ping report loss that real traffic does not see.',
   ['loss-throughput', 'parallel-flows'])],
 [mc('t544-a1', 'mathis-model', 'Under the Mathis model, what happens to one TCP flow’s throughput if loss rises from 0.01% to 0.04% on the same path?',
   [('a', 'It drops to about a quarter'), ('b', 'It drops by about 0.03%'), ('c', 'It roughly halves'), ('d', 'It stays the same until the link fills')], 'c',
   'Throughput scales with 1 ÷ √p; four times the loss gives √4 = 2, so half. A quarter would be a 1 ÷ p relation; the change is far larger than 0.03%; and the model has no link-capacity term.'),
  mc('t544-a2', 'parallel-flows', 'A 10 Gbit/s Mumbai to Frankfurt link (RTT about 120 ms) has 0.01% random loss, and a single-connection backup crawls. Which change helps most?',
   [('a', 'Upgrade the link to 40 Gbit/s'), ('b', 'Split the backup over several connections'), ('c', 'Give the backup server more CPU cores'), ('d', 'Lower the MTU to 576 bytes')], 'b',
   'Each flow gets its own loss-limited share, so parallel flows add up until the link fills. A bigger link leaves each flow’s cap unchanged; CPU is not the limit; and a smaller MTU shrinks the MSS, which lowers the cap further.'),
  mc('t544-a3', 'jitter', 'Why do voice calls usually conceal a lost packet instead of retransmitting it?',
   [('a', 'A retransmission arrives a round trip later, after its playout time'), ('b', 'UDP gives the receiver no way to ask the sender for a missing packet'), ('c', 'Lost audio packets are too rare to be worth handling'), ('d', 'A retransmission would need a new TCP handshake first')], 'a',
   'Audio plays on a deadline, and a resend costs at least one more round trip. Applications can and sometimes do request resends over UDP; losses are common enough to need handling; and media over UDP has no TCP handshake.'),
  mc('t544-a4', 'bufferbloat', 'While a big upload runs on a 10 Mbit/s home uplink, video calls lag by nearly a second. What is the likely cause?',
   [('a', 'The ISP throttles calls whenever uploads run'), ('b', 'DNS lookups for the call servers slow down while the uplink is busy'), ('c', 'The upload has used up the router’s NAT ports'), ('d', 'A deep router queue holds call packets behind the upload')], 'd',
   'A full queue on a slow link adds hundreds of ms for everything behind it. Throttling and DNS slowness do not produce steady second-long lag during calls, and one upload uses one or a few NAT ports.'),
  mc('t544-a5', 'jitter', 'Audio packets arrive with one-way delays between 40 and 90 ms. Roughly how much jitter buffer avoids late packets?',
   [('a', 'About 40 ms'), ('b', 'About 50 ms'), ('c', 'About 90 ms'), ('d', 'About 130 ms')], 'b',
   'The buffer covers the spread between the fastest and slowest packets: 90 − 40 = 50 ms. 40 and 90 ms are the delays themselves, and 130 ms adds them.'),
  order('t544-a6', 'loss-throughput', 'Sequence one tooth of the sawtooth a loss-based sender traces between drops.',
   ['A segment is lost in the network', 'The receiver sends duplicate ACKs for later segments', 'After three duplicate ACKs the sender retransmits', 'The sender cuts its congestion window', 'The window grows again until the next loss'],
   ['s3', 's5', 's2', 's1', 's4'], 'Fast retransmit then a window cut; the repeating cut and slow regrowth is what the Mathis model averages.'),
  est('t544-a7', 'mathis-model', 'One TCP flow has MSS 1,460 bytes, RTT 100 ms and random loss of 0.01%. Using throughput ≈ 1.22 × MSS ÷ (RTT × √p), about how many Mbit/s can it reach?', 'Mbit/s', 14.2,
   ['MSS 1,460 bytes = 11,680 bits', 'p = 0.0001, so √p = 0.01'],
   '1.22 × 11,680 ÷ (0.1 × 0.01)', '1.22 × 11,680 ÷ 0.001 ≈ 14,250,000 bit/s ≈ 14.2 Mbit/s',
   'Design implication: link speed is absent from the formula, so a faster link will not help this flow; a closer endpoint or less loss will.', 0.1, [1.42, 142, 116.8])],
 flash(544, [('Mathis model?', 'Throughput ≈ (MSS ÷ RTT) × 1.22 ÷ √p; link speed does not appear.'),
             ('Jitter buffer size?', 'About the spread between the fastest and slowest packet delays.'),
             ('Bufferbloat?', 'A deep queue at the bottleneck adding delay without adding throughput.')]),
 src([('Mathis et al.: The macroscopic behavior of the TCP congestion avoidance algorithm', 'https://dl.acm.org/doi/10.1145/263932.264023'),
      ('RFC 7567: IETF Recommendations Regarding Active Queue Management', 'https://www.rfc-editor.org/rfc/rfc7567'),
      ('RFC 3550: RTP, A Transport Protocol for Real-Time Applications', 'https://www.rfc-editor.org/rfc/rfc3550')]),
 deep(['loss-throughput', 'mathis-model', 'jitter', 'bufferbloat'], 'Why loss and delay shape what a flow can do',
  ['Classic congestion control treats each loss as a sign of congestion. On a loss the sender cuts its congestion window, by half in Reno and by about 30% in CUBIC, then grows it again by roughly one segment per round trip. Over many cycles the window saws up and down around an average that depends on how often losses happen.',
   'The Mathis model turns that sawtooth into a formula. If losses are random with probability p, the average window is about 1.22 ÷ √p segments, and one window is sent per round trip, so throughput ≈ (MSS ÷ RTT) × 1.22 ÷ √p. Link capacity is absent: the formula is a ceiling set by loss and delay, and the link only matters once the ceiling exceeds it.',
   'The model assumes no timeouts and enough receive window. Heavy loss causes retransmission timeouts and does worse than the formula; congestion control based on measured bandwidth and delay, such as BBR, does not cut on every loss and can do better on randomly lossy paths. It remains a good first estimate of why long, lossy paths are slow for one connection.',
   'Real-time traffic suffers from a different failure. Audio and video packets have deadlines: a 20 ms audio frame must play at its slot. The receiver’s jitter buffer absorbs variation in delay, and its depth is pure added latency. Late packets count as lost, and codecs hide small losses by interpolation, while forward error correction adds redundancy to repair some losses without waiting.',
   'Bufferbloat connects the two. Routers with large buffers let loss-based TCP fill them before any drop occurs, so the queue sits full and every packet waits behind it. Interactive traffic sharing the link sees the queue delay as lag. Active queue management, recommended by RFC 7567, drops or marks packets early, keeping queues short while bulk transfers still use the link fully.'],
  ['Estimating why a single long-distance transfer is slow.', 'Designing real-time audio, video or game traffic over lossy or variable links.'],
  ['Avoid using the Mathis model at very high loss, where timeouts dominate.', 'Avoid adding bandwidth before checking whether loss or delay caps the flow.'],
  ['Problem', 'Main effect', 'Typical remedy'],
  [['Random loss on a long path', 'Caps one TCP flow', 'Parallel flows, closer endpoints, less loss'],
   ['Jitter', 'Late packets for real-time media', 'Jitter buffer, loss concealment'],
   ['Bufferbloat', 'Seconds of queueing delay', 'Active queue management, rate limiting at the edge'],
   ['Congestion', 'Loss and delay for everyone', 'More capacity or less traffic']],
  'The cap on one cross-continent flow',
  ['MSS 1,460 bytes, RTT 100 ms', 'Random loss 0.01%', 'A 10 Gbit/s link that is otherwise idle'],
  ['MSS ÷ RTT: 11,680 bits ÷ 0.1 s = 116,800 bit/s.',
   '1.22 ÷ √0.0001 = 1.22 ÷ 0.01 = 122.',
   'Throughput ≈ 116,800 × 122 ≈ 14.2 Mbit/s.',
   'Flows needed to fill 1 Gbit/s at this cap: 1,000 ÷ 14.2 ≈ 70.'],
  'Loss and round-trip time, not link speed, set the ceiling for one flow; filling the link takes many flows or less loss.',
  'The Mathis model and queue management guidance', 'Official documentation',
  'Mathis, Semke, Mahdavi and Ott published the model in ACM SIGCOMM Computer Communication Review in 1997, showing that a sustained TCP flow under light to moderate loss achieves bandwidth proportional to MSS ÷ (RTT × √p), and checking it against simulations and live internet measurements. RFC 7567 recommends that network equipment use active queue management by default to avoid the persistent large queues that cause bufferbloat.',
  [('“The link is 10 Gbit/s, so the transfer should take seconds.”', '“With 100 ms RTT and 0.01% loss, one flow caps near 14 Mbit/s; I’d use parallel flows or cut the loss.”'),
   ('“Calls lag, so we need a faster connection.”', '“If calls lag only during uploads, it is queueing delay; active queue management fixes it without more bandwidth.”')],
  ['One TCP flow’s ceiling ≈ (MSS ÷ RTT) × 1.22 ÷ √p, independent of link speed.', 'Doubling RTT halves the ceiling; four times the loss also halves it.', 'A jitter buffer must cover the delay spread, and its depth is added latency.', 'Bufferbloat is a full queue; active queue management keeps it short.']),
 predict('Which path is faster for one flow?',
  'You copy one large file over a single TCP connection. Path A has a 10 ms round trip and 0.04% loss. Path B has a 40 ms round trip and 0.01% loss. Both links are 1 Gbit/s. Which finishes first?',
  [('a', 'Path B, since it loses a quarter as many packets', 'Loss enters as a square root: four times the loss costs only a factor of two, while B’s round trip is four times longer.'),
   ('b', 'Path A, at about twice B’s throughput', 'Right: RTT × √p is 10 × 0.02 = 0.2 for A and 40 × 0.01 = 0.4 for B, so A’s ceiling is twice B’s.'),
   ('c', 'About the same, since both links are 1 Gbit/s', 'Neither flow gets near 1 Gbit/s; loss and round trip set the ceiling, not link speed.')],
  'b', 'Throughput scales with 1 ÷ (RTT × √p). A: 10 × √0.0004 = 0.2; B: 40 × √0.0001 = 0.4. The smaller product wins by a factor of two, so the shorter path beats the cleaner one here.'),
 see([(248, 'Congestion windows and slow start are the mechanism the Mathis model averages'), (253, 'Latency and bandwidth are separate limits, and this lesson adds loss as a third'), (5, 'Why real-time media often prefers UDP over TCP')])))

# ---------------------------------------------------------------- 545 STUN, TURN, ICE
T.append(topic(545, 'nat-traversal-stun-turn-ice', R, 19, 'Peer-to-Peer Connections: STUN, TURN and ICE',
 ['Explain why two devices behind NAT cannot simply connect to each other',
  'Describe how ICE gathers and tests candidates using STUN and TURN',
  'Estimate the relay cost when direct paths fail'],
 3, 12, [244, 249],
 [text(545, 1, 'Why two devices behind NAT cannot just connect',
   'A NAT creates a mapping only when a packet goes out, and it drops unsolicited packets coming in. When both peers sit behind NATs, neither can be the first to receive, and neither knows the public address and port the other’s NAT will use. Peers therefore exchange addresses through a server they can both reach, called the signalling channel; ICE leaves its format to the application.',
   ['nat-traversal']),
  diagram(545, 2, 'ICE tries every path and keeps the best',
   'Interactive Connectivity Establishment (ICE) collects possible addresses and tests them in pairs.', ['ice-candidates', 'nat-traversal'],
   ['Gather host candidates: the device’s own addresses',
    'Ask a STUN server for a server-reflexive candidate: the public address and port the NAT assigned',
    'Ask a TURN server for a relayed candidate: an address on the relay',
    'Swap candidates over signalling, then both peers send connectivity checks to each pair at once',
    'Outbound checks open NAT mappings for the other side’s checks; the best working pair is nominated']),
  text(545, 3, 'STUN discovers, TURN relays',
   'A STUN server answers one question: from what address and port do you see me? It is cheap and stays out of the media path. A TURN server allocates a relay address and forwards every packet between the peers, so it works through nearly any NAT or firewall that allows outbound traffic, including over TCP or TLS on port 443, but it carries the full media stream and adds the detour’s latency. ICE prefers direct pairs and uses the relay only when nothing direct works.',
   ['stun', 'turn-relay']),
  worked(545, 4, 'Worked example: the bandwidth bill for relayed calls',
   'A relay carries both directions of every call it serves.', ['turn-relay'],
   ['Assume: a one-to-one video call sends 1.5 Mbit/s in each direction',
    'Relayed, the server receives 1.5 Mbit/s from each peer: 3 Mbit/s in',
    'It forwards each stream to the other peer: 3 Mbit/s out',
    '1,000 concurrent relayed calls: 1,000 × 3 = 3,000 Mbit/s = 3 Gbit/s out',
    'One hour at that rate: 3 Gbit/s × 3,600 s ÷ 8 = 1,350 GB of egress'],
   'Result. In this illustrative case every relayed call costs real egress, while a direct call costs the operator nothing beyond signalling. That is why ICE tries direct paths first, and why relays are sized for the share of users who need them.'),
  text(545, 5, 'Trap: expecting hole punching through every NAT',
   'Hole punching relies on the NAT reusing the same public port for a device whatever destination it talks to, which RFC 4787 calls endpoint-independent mapping. Some NATs, including some carrier-grade and enterprise ones, assign a new port for each destination. The port STUN reported is then wrong for the peer, the checks fail, and only TURN connects. Plan for relays rather than assuming direct paths.',
   ['nat-mapping']),
  text(545, 6, 'Keeping the path open once it works',
   'NAT mappings for UDP expire when idle; RFC 4787 requires at least two minutes and recommends five. A call that pauses its media, or a data channel that goes quiet, must send small keepalives well inside that window, or the mapping vanishes and packets are dropped. Mobile devices that switch networks get new addresses, so ICE restarts to find a new pair.',
   ['nat-mapping'])],
 [mc('t545-a1', 'stun', 'What does a STUN server tell a client?',
   [('a', 'The private address of the peer it wants to call'), ('b', 'The public address and port its NAT mapped it to'), ('c', 'Which relay server should carry the media'), ('d', 'The keys used to encrypt the media stream')], 'b',
   'STUN reflects back the address it saw. It knows nothing about the peer’s private address; relays come from TURN; and media keys are negotiated separately between the peers.'),
  mc('t545-a2', 'turn-relay', 'When does ICE fall back to a TURN relay?',
   [('a', 'When no direct candidate pair passes its checks'), ('b', 'Whenever the two peers use different ISPs'), ('c', 'When a call carries more than two video streams'), ('d', 'When the STUN server is in another region')], 'a',
   'The relayed pair is the last resort. Different ISPs connect directly all the time; stream count does not decide the path; and STUN server location affects only discovery latency.'),
  mc('t545-a3', 'nat-mapping', 'Direct calls fail for users on one mobile network. STUN shows them a different public port for each server they contact. Why do direct calls fail?',
   [('a', 'The network blocks every STUN request'), ('b', 'Their phones have no IPv4 address at all'), ('c', 'Their NAT keeps mappings open far too long'), ('d', 'Their NAT maps a new port per destination')], 'd',
   'With endpoint-dependent mapping, the port learned from STUN differs from the one used toward the peer. A blocked STUN would give no reflexive address at all; IPv6-only phones still get candidates; and long-lived mappings help rather than hurt.'),
  mc('t545-a4', 'ice-candidates', 'Which candidate types does ICE gather?',
   [('a', 'Host, server-reflexive and relayed'), ('b', 'Primary, secondary and backup'), ('c', 'Private, public and multicast'), ('d', 'Unicast, anycast and broadcast')], 'a',
   'Local addresses, the NAT’s public mapping from STUN, and a relay address from TURN. The other sets name DNS roles or address kinds, not ICE candidates.'),
  mc('t545-a5', 'nat-traversal', 'Why do both peers send connectivity checks at about the same time?',
   [('a', 'Checks only count when they collide in the network'), ('b', 'Each outbound check opens a mapping the other’s checks can use'), ('c', 'NATs require both peers to share a clock'), ('d', 'The peers must agree on a shared codec before any media can start')], 'b',
   'A NAT accepts inbound packets from an address it has just sent to, so simultaneous checks punch holes for each other. Collisions are not required; NATs keep no shared clock; and codecs are negotiated in signalling.'),
  order('t545-a6', 'ice-candidates', 'Order the steps of setting up a peer-to-peer connection with ICE.',
   ['Gather host, reflexive and relayed candidates', 'Exchange candidates over signalling', 'Pair candidates and run connectivity checks', 'Nominate the best working pair', 'Send media and keep the mapping alive'],
   ['s2', 's4', 's1', 's5', 's3'], 'Discover, exchange, test, choose, then use and keep alive.'),
  est('t545-a7', 'turn-relay', 'A relayed one-to-one call sends 1.5 Mbit/s each way. How many Gbit/s does a TURN server send out for 1,000 such calls?', 'Gbit/s', 3,
   ['The relay forwards each direction once', '1,000 calls are relayed at the same time'],
   '1,000 × 2 × 1.5 Mbit/s', '1,000 × 3 Mbit/s = 3,000 Mbit/s = 3 Gbit/s',
   'Design implication: relay capacity scales with the share of calls that need it, so a few percent more relayed users can mean several more relay servers.', 0.05, [1.5, 6])],
 flash(545, [('STUN?', 'Tells a client the public address and port its NAT assigned.'),
             ('TURN?', 'A relay that forwards all media when no direct path works.'),
             ('ICE?', 'Gathers host, reflexive and relayed candidates, tests pairs, keeps the best.')]),
 src([('RFC 8445: Interactive Connectivity Establishment (ICE)', 'https://www.rfc-editor.org/rfc/rfc8445'),
      ('RFC 8489: Session Traversal Utilities for NAT (STUN)', 'https://www.rfc-editor.org/rfc/rfc8489'),
      ('RFC 8656: Traversal Using Relays around NAT (TURN)', 'https://www.rfc-editor.org/rfc/rfc8656'),
      ('MDN: Introduction to WebRTC protocols', 'https://developer.mozilla.org/en-US/docs/Web/API/WebRTC_API/Protocols')]),
 deep(['nat-traversal', 'ice-candidates', 'turn-relay'], 'How ICE finds a path between two NATs',
  ['Each peer starts by gathering candidates. Host candidates are its own interface addresses, useful when both peers share a network. It then sends a STUN request to a public server, which replies with the source address and port it saw, giving a server-reflexive candidate. Finally it can ask a TURN server to allocate a relay address, giving a relayed candidate.',
   'The peers swap candidate lists through the application’s signalling channel, often a WebSocket to the app’s server. ICE does not define this channel. Each side then forms pairs of its candidates with the other’s and sorts them by priority, preferring host, then reflexive, then relayed, because direct paths are faster and cost nothing to relay.',
   'Connectivity checks are STUN requests sent directly between the peers on each pair. When peer A sends to B’s reflexive address, A’s NAT creates a mapping that lets B’s packets in; B does the same in the other direction. If both NATs keep the same public port regardless of destination, the checks meet and the pair works. This is hole punching.',
   'If a NAT allocates a new port per destination, the reflexive port B learned for A is not the one A’s NAT uses toward B, and checks fail. Pairs that include the relayed candidate still work, because each peer only talks outbound to the TURN server, which forwards between them. The relay costs bandwidth in both directions and adds latency.',
   'Once a pair is nominated, media flows and the peers keep the NAT mappings warm with periodic packets. Consent checks confirm the peer still wants the traffic. If a device changes network, for example from Wi-Fi to mobile data, its candidates change and the peers run an ICE restart to find a new working pair.'],
  ['Voice, video and data channels between browsers or apps that should not route through your servers.', 'Any peer-to-peer feature where users sit behind home, mobile or office NATs.'],
  ['Avoid shipping without a TURN fallback; some users will have no direct path.', 'Avoid peer-to-peer meshes for large group calls; a media server scales better past a handful of peers.'],
  ['Path', 'Latency', 'Operator cost', 'Works through'],
  [['Direct (host or reflexive)', 'Lowest', 'Signalling only', 'Most home NATs'],
   ['Relayed via TURN', 'Higher, via the relay', 'Full media bandwidth', 'Nearly any NAT or firewall'],
   ['Media server (not peer-to-peer)', 'Via the server', 'Full bandwidth, plus processing', 'Any network that reaches the server']],
  'Relay capacity for a calling app',
  ['1.5 Mbit/s each way per one-to-one video call', '1,000 calls need a relay at peak', 'Relay servers with 10 Gbit/s network cards, run at 50% for headroom'],
  ['Each relayed call: 1.5 × 2 = 3 Mbit/s out of the relay.',
   'Peak relay egress: 1,000 × 3 Mbit/s = 3 Gbit/s.',
   'Usable per server: 10 Gbit/s × 0.5 = 5 Gbit/s, so one server carries the load.',
   'Spread over two regions for failure tolerance: at least two servers, one per region.'],
  'Relays are cheap to run in small numbers but scale with how many users fail to connect directly, so measure that share.',
  'NAT traversal in the IETF standards', 'Official documentation',
  'RFC 8445 defines ICE: candidate gathering, pairing, connectivity checks and nomination. RFC 8489 defines STUN, including how a server reports the reflexive transport address. RFC 8656 defines TURN allocations and permissions on the relay. RFC 4787 sets behavioural requirements for NATs handling UDP, recommending endpoint-independent mapping precisely so that applications such as these can reach peers without relays.',
  [('“STUN is enough; relays are an edge case.”', '“Some users sit behind NATs that map per destination, so I’d always deploy TURN and size it from the measured relay share.”'),
   ('“Peer-to-peer means we pay no bandwidth.”', '“Direct calls cost us nothing, but every relayed call costs its full bitrate in both directions.”')],
  ['NATs drop unsolicited inbound packets, so peers need help to connect.', 'STUN finds a public mapping; TURN relays media when nothing direct works.', 'ICE gathers candidates, tests pairs from both sides and keeps the best.', 'Relay cost is twice the call bitrate per relayed call.']),
 predict('Pick a NAT-traversal setup', 
  'You are launching one-to-one video calls in a mobile app. Users are on home Wi-Fi, mobile networks and office networks. Which setup do you ship?',
  [('a', 'STUN only, with no relays to pay for', 'Cheapest, but users behind NATs that map per destination, or offices that block UDP, cannot connect at all.'),
   ('b', 'ICE with STUN, plus TURN as a fallback', 'Right: direct paths for most calls, and a relay for the rest, so everyone connects and you pay only for relayed calls.'),
   ('c', 'Relay every call through TURN servers', 'Everyone connects, but you pay full bandwidth for every call and add latency even where a direct path existed.')],
  'b', 'ICE exists to get the best of both: it tries direct pairs first and falls back to the relay. Plan relay capacity from the measured share of relayed calls, and offer TURN over TCP or TLS on port 443 for networks that block UDP.', kind='tradeoff'),
 see([(244, 'How NAT tables map private addresses and ports to public ones'), (218, 'Real-time channels on the client, often the signalling path for calls'), (249, 'UDP and port behaviour that hole punching relies on')])))

# ---------------------------------------------------------------- 546 email delivery
T.append(topic(546, 'email-delivery-spf-dkim-dmarc', R, 20, 'Email Delivery: SMTP, SPF, DKIM and DMARC',
 ['Trace how a message moves between mail servers with SMTP and MX records',
  'Explain what SPF, DKIM and DMARC each check, and why alignment matters',
  'Roll out a DMARC policy without losing legitimate mail'],
 2, 12, [246],
 [text(546, 1, 'How a message hops between mail servers',
   'An app hands mail to its provider’s submission server, usually on port 587 with authentication. That server looks up the recipient domain’s MX records and connects to the listed mail server on port 25. The receiver answers each step with a code: 2xx accepts, 5xx rejects permanently and the sender bounces the message, 4xx means try later. RFC 5321 asks senders to wait at least 30 minutes between retries and to keep trying for at least four to five days.',
   ['smtp-relay', 'email-retries']),
  diagram(546, 2, 'Three checks a receiver runs',
   'SPF and DKIM authenticate domains; DMARC ties them to the From address people see.', ['spf', 'dkim', 'dmarc-alignment'],
   ['SPF: is the connecting IP allowed by the SPF record of the envelope sender’s domain (MAIL FROM)?',
    'DKIM: does the signature verify with the public key at selector._domainkey of the signing domain d=?',
    'DMARC: did SPF or DKIM pass for a domain that aligns with the visible From domain?',
    'If not, apply the From domain’s policy: none, quarantine or reject',
    'Send aggregate reports to the address the domain published, so its owner sees failures']),
  worked(546, 3, 'Worked example: SPF passes but DMARC fails',
   'Passing checks for the wrong domain does not satisfy DMARC.', ['dmarc-alignment'],
   ['A shop sends From: billing@shop.example through an email provider',
    'Envelope sender is bounces@mail.provider.example: SPF passes, for provider.example',
    'DKIM signature has d=provider.example: DKIM passes, for provider.example',
    'Neither domain aligns with shop.example, so DMARC fails; with p=reject the mail is refused'],
   'Result. Two passing checks still fail DMARC. The fix is to sign with d=shop.example using a key the shop publishes, and to use a return-path such as bounce.shop.example, which aligns under the default relaxed rules.'),
  text(546, 4, 'SPF stops at ten lookups',
   'RFC 7208 limits the mechanisms that cost DNS queries, such as include, a, mx and redirect, to 10 per check. Each provider’s include can contain more includes, and once the count passes 10, SPF returns a permanent error, which DMARC treats as a fail. SPF also breaks when mail is forwarded, because the forwarder’s IP is not in the original domain’s record. A DKIM signature travels with the message and survives forwarding unless the content changes, which is why DMARC needs only one of the two to pass and align.',
   ['spf', 'dkim']),
  text(546, 5, 'Trap: jumping straight to p=reject',
   'Companies send mail from many places: the app, a support desk, a marketing tool, payroll. Publishing p=reject first silently drops every sender that is not yet aligned. Start with p=none and a reporting address, read the aggregate reports for a few weeks, fix each legitimate sender, then move to quarantine and finally reject. DMARC is now specified in RFC 9989 (2026), which replaced RFC 7489.',
   ['dmarc-alignment'])],
 [mc('t546-a1', 'smtp-relay', 'How does a sending mail server find where to deliver mail for someone@example.org?',
   [('a', 'It looks up the MX records for example.org'), ('b', 'It posts the message to example.org’s web server on port 443'), ('c', 'It reads the delivery address from example.org’s SPF record'), ('d', 'It asks the recipient’s ISP for a route over BGP')], 'a',
   'MX records name the mail servers for a domain. Web servers do not accept mail; SPF lists who may send for a domain, not where to deliver; and BGP routes packets, not messages.'),
  mc('t546-a2', 'email-retries', 'A receiving server answers a delivery attempt with code 451. What should the sender do?',
   [('a', 'Bounce the message to its author at once'), ('b', 'Resend it in a tight loop until accepted'), ('c', 'Queue it and retry later, for days if needed'), ('d', 'Drop it, since 4xx means the address is wrong')], 'c',
   'A 4xx reply is temporary, so the sender queues and retries with growing gaps. Bouncing is for 5xx; tight loops look like abuse and get blocked; and a wrong address returns a 5xx.'),
  mc('t546-a3', 'dmarc-alignment', 'SPF passes for mail.provider.example, DKIM passes with d=provider.example, and the visible From is shop.example. What does DMARC conclude?',
   [('a', 'Pass, since both SPF and DKIM passed'), ('b', 'Fail, since neither passing domain aligns with shop.example'), ('c', 'Pass, as long as the provider’s IPs are listed in the SPF record'), ('d', 'Neutral, since DMARC looks only at DKIM')], 'b',
   'DMARC needs a pass for a domain matching the From domain. Both passes are for provider.example; listing IPs does not change which domain passed; and DMARC uses both SPF and DKIM.'),
  mc('t546-a4', 'spf', 'An SPF record includes six providers that together need 13 DNS lookups. What happens?',
   [('a', 'Receivers evaluate the first 10 and accept the rest'), ('b', 'Caching makes the lookup limit not apply'), ('c', 'SPF passes, but with a lower spam score'), ('d', 'Evaluation hits a permanent error and SPF fails')], 'd',
   'Past 10 lookups RFC 7208 requires a permanent error. Receivers do not skip ahead; caching does not change the count; and a permerror is not a pass.'),
  mc('t546-a5', 'dkim', 'Why does DKIM often survive mail forwarding when SPF does not?',
   [('a', 'The signature travels with the message, but SPF checks the forwarder’s IP'), ('b', 'Forwarders sign each message again using the original sending domain’s key'), ('c', 'Receivers turn off SPF checks for forwarded mail'), ('d', 'DKIM checks the recipient’s domain rather than the sender’s')], 'a',
   'DKIM verifies content plus the signing domain’s key, wherever the message came from. Forwarders do not hold the original private key; receivers still run SPF; and DKIM verifies the signing domain, not the recipient.'),
  order('t546-a6', 'dmarc-alignment', 'Order a safe DMARC rollout.',
   ['Publish SPF and DKIM for every sending service', 'Publish DMARC with p=none and a reporting address', 'Read aggregate reports and fix unaligned senders', 'Move the policy to quarantine', 'Move the policy to reject'],
   ['s3', 's1', 's5', 's2', 's4'], 'Authenticate, observe, fix, then tighten in steps so no legitimate sender is lost.'),
  est('t546-a7', 'spf', 'An SPF record has include:a.example (which itself holds 2 includes), include:b.example (which holds 3), plus mx and a. How many DNS lookups count toward the limit?', 'lookups', 9,
   ['Each include, mx and a costs one lookup', 'Nested includes count too', 'The nested includes contain no further lookups'],
   '(1 + 2) + (1 + 3) + 1 + 1', '3 + 4 + 1 + 1 = 9 lookups',
   'Sanity check: nine of ten leaves room for just one more lookup, so adding another provider’s include could tip SPF into a permanent error.', 0, [4, 5, 10])],
 flash(546, [('SPF checks?', 'Whether the sending IP is allowed by the envelope sender domain’s record; at most 10 lookups.'),
             ('DKIM checks?', 'A signature over the message, verified with the signing domain’s public key in DNS.'),
             ('DMARC adds?', 'Alignment: SPF or DKIM must pass for the visible From domain, plus a policy and reports.')]),
 src([('RFC 5321: Simple Mail Transfer Protocol', 'https://www.rfc-editor.org/rfc/rfc5321'),
      ('RFC 7208: Sender Policy Framework (SPF)', 'https://www.rfc-editor.org/rfc/rfc7208'),
      ('RFC 6376: DomainKeys Identified Mail (DKIM) Signatures', 'https://www.rfc-editor.org/rfc/rfc6376'),
      ('RFC 9989: Domain-Based Message Authentication, Reporting, and Conformance (DMARC)', 'https://www.rfc-editor.org/rfc/rfc9989')]),
 deep(['smtp-relay', 'spf', 'dkim', 'dmarc-alignment'], 'What happens between “send” and the inbox',
  ['An application submits a message to a mail server it is allowed to use, authenticating on the submission port. The message has two sets of addresses: the envelope, used by SMTP for routing and bounces (MAIL FROM and RCPT TO), and the headers people see, including From. They often differ, for example when a provider handles bounces on its own domain.',
   'The sending server resolves the recipient domain’s MX records, picks the lowest preference value first, and opens an SMTP session. The receiver can reject at any step with a 5xx code or defer with a 4xx. Deferred mail stays in the sender’s queue and is retried with backoff, so a temporary problem at the receiver delays mail by minutes or hours rather than losing it.',
   'The receiver then authenticates. SPF looks up a TXT record on the envelope sender’s domain and asks whether the connecting IP is listed, directly or through includes. DKIM finds a signature header, fetches the public key at the selector the header names, and verifies a hash over the body and chosen headers. Each produces a result for a specific domain, which may not be the one in From.',
   'DMARC closes that gap. It looks up a policy record at _dmarc on the From domain and requires that SPF or DKIM pass for an aligned domain: the same organisational domain under relaxed alignment, or the exact domain under strict alignment. If neither aligns, the receiver applies the policy, none, quarantine or reject, though it may still use its own judgement.',
   'DMARC also asks receivers to send aggregate reports: daily XML summaries of which IPs sent mail claiming the domain and how they fared. These reports are how a domain owner finds forgotten senders before tightening the policy, and how it spots spoofing. Transport security is separate: STARTTLS is opportunistic by default, and MTA-STS lets a domain require TLS for mail sent to it.'],
  ['Any product that sends password resets, receipts or notifications from its own domain.', 'Protecting a brand domain from being spoofed in phishing.'],
  ['Avoid publishing p=reject before reports show every legitimate sender aligned.', 'Avoid stacking provider includes until SPF passes 10 lookups.'],
  ['Check', 'Verifies', 'Breaks when'],
  [['SPF', 'Sending IP is authorised for the envelope domain', 'Mail is forwarded; more than 10 lookups'],
   ['DKIM', 'Signature from the signing domain’s key', 'A list or gateway modifies the signed content'],
   ['DMARC', 'An aligned SPF or DKIM pass for the From domain', 'Senders pass only for their own domain']],
  'Counting an SPF record',
  ['include:a.example holding 2 more includes', 'include:b.example holding 3 more includes', 'mx and a mechanisms on the domain itself'],
  ['Provider A: 1 lookup for the include plus 2 nested = 3.',
   'Provider B: 1 plus 3 nested = 4.',
   'The mx and a mechanisms: 1 each = 2.',
   'Total 3 + 4 + 2 = 9 of the 10 allowed; one more provider include with any nesting tips it over.'],
  'The record works today but is one vendor away from a permanent error, so flatten it or move a sender to its own subdomain.',
  'SMTP, SPF, DKIM and DMARC in the RFCs', 'Official documentation',
  'RFC 5321 defines SMTP, MX-based delivery and the retry guidance of at least 30 minutes between attempts and four to five days before giving up. RFC 7208 defines SPF and its 10-lookup limit. RFC 6376 defines DKIM signatures and key lookup. RFC 9989, published in May 2026, is the standards-track DMARC specification that replaced RFC 7489, with RFC 9990 and RFC 9991 covering aggregate and failure reports.',
  [('“SPF and DKIM both pass, so DMARC is fine.”', '“They have to pass for a domain aligned with From; passing for the provider’s domain still fails DMARC.”'),
   ('“Let’s publish p=reject today.”', '“I’d start at p=none, read the reports, fix each sender, then tighten.”')],
  ['Mail routes by MX records; 4xx means retry later, 5xx means bounce.', 'SPF authorises sending IPs and allows at most 10 DNS lookups.', 'DKIM signs the message and survives forwarding unless content changes.', 'DMARC needs an aligned pass for the From domain; roll out from p=none.']),
 predict('Where did the password resets go?',
  'Yesterday you changed your domain’s DMARC policy from none to reject. Today support says password-reset mails sent by your helpdesk vendor are not arriving. Your app’s own mail still arrives. What happened?',
  [('a', 'A reject policy blocks every automated sender', 'DMARC does not care whether mail is automated; your app’s mail still arrives because it is aligned.'),
   ('b', 'DMARC records take about a week to take effect', 'A DMARC record is a DNS TXT record; it takes effect as caches expire, typically within hours.'),
   ('c', 'The vendor sends as your domain without aligned SPF or DKIM', 'Right: the vendor’s mail passes only for its own domain, so DMARC fails and receivers now reject it.')],
  'c', 'Every service that sends as your domain needs aligned SPF or DKIM, usually by adding a DKIM key the vendor provides under your domain. Aggregate reports under p=none would have shown this sender failing before the switch.'),
 see([(6, 'MX, TXT and the DNS lookups every mail check depends on'), (40, 'Idempotent sends keep mail retries from producing duplicates'), (246, 'How resolvers cache the records SPF, DKIM and DMARC fetch')])))

# ---------------------------------------------------------------- 547 DDoS
T.append(topic(547, 'ddos-floods-and-amplification', R, 21, 'DDoS: Floods, Amplification and Absorption',
 ['Tell apart volumetric, protocol and application-layer floods',
  'Explain SYN floods, SYN cookies and reflection amplification',
  'Decide where each kind of attack must be absorbed or filtered'],
 3, 12, [247, 249],
 [text(547, 1, 'Three ways to exhaust a service',
   'A volumetric attack fills the pipes, measured in Gbit/s, so nothing behind the link matters. A protocol attack exhausts state in servers or middleboxes, such as half-open TCP connections or a firewall’s connection table. An application-layer attack sends valid-looking requests that are expensive to serve, such as searches or logins, measured in requests per second. Each needs a defence in a different place.',
   ['ddos-types']),
  diagram(547, 2, 'How a SYN flood fills the queue, and how SYN cookies empty it',
   'The attacker sends SYNs but never completes the handshake.', ['syn-flood', 'syn-cookies'],
   ['The attacker sends SYNs with forged source addresses',
    'The server stores a half-open entry and sends SYN-ACKs to the forged addresses',
    'Entries wait for an ACK that never comes, through several SYN-ACK retries',
    'The half-open queue fills and real clients’ SYNs are dropped',
    'With SYN cookies the server encodes the connection details in its sequence number, stores nothing, and rebuilds the entry from a valid ACK']),
  worked(547, 3, 'Worked example: sizing a reflection attack',
   'Reflection sends a small spoofed request to a server that sends a large reply to the victim.', ['amplification'],
   ['Assume: a 64-byte query with the victim’s address as source triggers a 3,200-byte answer',
    'Amplification factor: 3,200 ÷ 64 = 50',
    'Attackers send 1 Gbit/s of spoofed queries to many open servers',
    'The victim receives 1 × 50 = 50 Gbit/s of answers',
    'Against a 10 Gbit/s uplink, that is five times the capacity'],
   'Result. In this illustrative case the link is full before any packet reaches a server, so nothing on the server can help. The flood must be absorbed by networks with more capacity than the attack.'),
  text(547, 4, 'Absorb at the edge, before your link',
   'Volumetric floods are absorbed upstream: anycast spreads them over many sites, and scrubbing services filter at a scale no single site has. Hide the origin by accepting traffic only from the CDN or proxy in front of it. Providers that apply source-address validation (BCP 38) stop their customers from sending spoofed packets, which removes reflection at its root. Application floods are handled closer in: caching, rate limits per client or key, and challenges for suspicious traffic.',
   ['ddos-absorption', 'l7-flood']),
  text(547, 5, 'Trap: blocking the attacking addresses',
   'In a SYN flood the source addresses are forged; in a reflection attack they belong to innocent open servers; in an application flood they may be tens of thousands of home devices. Blocking addresses one by one cannot keep up and can block real users. Filter by what the traffic is instead: drop unexpected UDP from ports 53, 123 or 11211 at the edge of a web service, rate-limit expensive endpoints, and challenge clients that look automated.',
   ['ddos-absorption', 'amplification'])],
 [mc('t547-a1', 'syn-flood', 'During a SYN flood, real users cannot connect though the server’s CPU is mostly idle. Why?',
   [('a', 'Half-open entries fill the queue, so new SYNs are dropped'), ('b', 'The server has run out of TLS session keys for new clients'), ('c', 'The attack has taken every port on the server'), ('d', 'Forged packets have corrupted the routing table')], 'a',
   'The limit is the half-open queue, not CPU. TLS has not started for half-open connections; a server port serves many connections, so ports are not used up; and forged sources do not alter routes.'),
  mc('t547-a2', 'syn-cookies', 'What do SYN cookies change?',
   [('a', 'Clients must solve a puzzle before sending a SYN'), ('b', 'The server holds no state until the client’s ACK returns'), ('c', 'The server attaches a browser cookie to its SYN-ACK'), ('d', 'A firewall blocks addresses that send many SYNs')], 'b',
   'The connection details ride in the server’s initial sequence number, so forged SYNs cost no memory. There is no client puzzle in TCP; browser cookies are an HTTP feature; and source blocking is a separate, weaker defence.'),
  mc('t547-a3', 'amplification', 'Why do reflection attacks use UDP services such as DNS rather than TCP ones?',
   [('a', 'UDP packets are always larger than TCP packets'), ('b', 'TCP services cannot be reached from the internet'), ('c', 'With no handshake, a forged source gets the full reply'), ('d', 'DNS servers keep no log of who sent which query to them')], 'c',
   'TCP would send only a SYN-ACK to the forged address and stop, while UDP answers at once in full. Packet size depends on content, not the protocol; TCP services are reachable; and logging does not decide what gets reflected.'),
  mc('t547-a4', 'ddos-absorption', 'A 300 Gbit/s flood targets a site with a 10 Gbit/s uplink. Where must it be stopped?',
   [('a', 'In the application’s request handlers'), ('b', 'Upstream, in networks bigger than the flood'), ('c', 'With firewall rules on each web server'), ('d', 'By autoscaling web servers behind the uplink')], 'b',
   'Once the uplink is full, everything behind it starves. Handlers, host firewalls and extra servers all sit behind the saturated link.'),
  mc('t547-a5', 'l7-flood', 'Valid HTTPS search requests from 50,000 home IP addresses overload the database. What fits best?',
   [('a', 'Block each attacking address by hand'), ('b', 'Turn on SYN cookies on the web servers'), ('c', 'Raise the uplink from 10 to 40 Gbit/s'), ('d', 'Cache and rate-limit searches, and challenge bots')], 'd',
   'The cost is per request, so reduce the work per request and the number of requests per client. Hand-blocking cannot keep up; the handshakes complete, so SYN cookies do nothing; and the link is not the bottleneck.'),
  order('t547-a6', 'syn-flood', 'Order the stages of a SYN flood without SYN cookies.',
   ['Forged SYNs arrive', 'The server stores half-open entries', 'SYN-ACKs go to forged addresses and get no reply', 'The half-open queue fills', 'Real clients’ SYNs are dropped'],
   ['s4', 's2', 's5', 's3', 's1'], 'Each forged SYN costs an entry until it times out, so the queue fills and real users are turned away.'),
  est('t547-a7', 'amplification', 'A 64-byte spoofed query triggers a 3,200-byte reply. Attackers send 1 Gbit/s of such queries. How many Gbit/s reach the victim?', 'Gbit/s', 50,
   ['Every query is answered', 'Replies all go to the victim'],
   '1 × 3,200 ÷ 64', '3,200 ÷ 64 = 50, so 1 × 50 = 50 Gbit/s',
   'Design implication: 50 Gbit/s is more than most single sites can take in, so defence has to live upstream, not on the servers.', 0.05, [3.2, 64])],
 flash(547, [('Three DDoS kinds?', 'Volumetric (fills links), protocol (exhausts state), application (expensive requests).'),
             ('SYN cookies?', 'The server stores nothing for a SYN; it rebuilds state from the returning ACK.'),
             ('Amplification factor?', 'Reply size ÷ request size; the victim gets attack rate × factor.')]),
 src([('RFC 4987: TCP SYN Flooding Attacks and Common Mitigations', 'https://www.rfc-editor.org/rfc/rfc4987'),
      ('RFC 2827 (BCP 38): Network Ingress Filtering', 'https://www.rfc-editor.org/rfc/rfc2827'),
      ('AWS: Best Practices for DDoS Resiliency', 'https://docs.aws.amazon.com/whitepapers/latest/aws-best-practices-ddos-resiliency/welcome.html')]),
 deep(['ddos-types', 'syn-flood', 'amplification', 'ddos-absorption'], 'Where each flood bites and where it is stopped',
  ['Every service has a narrowest point: link capacity, a table of connection state, or the work per request. A denial-of-service attack aims at one of them. Distributed attacks use many sources, from botnets of compromised devices to reflection through innocent servers, so they cannot be stopped by blocking one sender.',
   'A SYN flood targets the TCP handshake. For each SYN, a server normally allocates an entry, sends a SYN-ACK and waits, resending a few times. Forged SYNs never complete, so entries pile up until the queue is full and real SYNs are dropped. SYN cookies, described in RFC 4987, let the server skip the entry: it encodes the connection details and a secret-keyed hash into its initial sequence number, and rebuilds them when a valid ACK returns.',
   'Reflection attacks forge the victim’s address as the source of small UDP queries to servers that answer with much larger replies: open DNS resolvers, time servers or misconfigured caches. The victim receives the replies from thousands of legitimate-looking servers. The amplification factor, reply size divided by request size, multiplies the attacker’s bandwidth, and spoofing is possible only where networks do not apply ingress filtering as BCP 38 recommends.',
   'Volumetric attacks must be absorbed where capacity exceeds the flood. Anycast announces the service from many sites so the flood splits among them, and providers’ scrubbing centres drop attack traffic by protocol, port and pattern before forwarding clean traffic. The origin should accept traffic only from the edge, so attackers cannot bypass it by aiming straight at the origin’s address.',
   'Application-layer floods look like real users and arrive over completed connections, so network filters cannot tell them apart. Defences work per request: cache expensive responses, rate-limit by client, account or key, require challenges for suspicious clients, and shed load before the database falls over. Autoscaling helps briefly but turns an attack into a large bill if no limit is set.'],
  ['Any public service, since a modest flood can fill a small site’s link.', 'Designing an origin behind a CDN, load balancer or scrubbing service.'],
  ['Avoid relying on per-address blocking against forged or widely distributed sources.', 'Avoid unlimited autoscaling as the only defence against request floods.'],
  ['Attack', 'Exhausts', 'Defence'],
  [['Volumetric or reflection', 'Link capacity', 'Upstream absorption, anycast, scrubbing'],
   ['SYN flood', 'Half-open connection state', 'SYN cookies, larger queues, edge proxies'],
   ['Application flood', 'Work per request', 'Caching, rate limits, challenges, load shedding']],
  'Can the uplink survive a reflection attack?',
  ['64-byte spoofed query, 3,200-byte reply', 'Attackers send 1 Gbit/s of queries', 'The site has a 10 Gbit/s uplink'],
  ['Amplification: 3,200 ÷ 64 = 50.',
   'Arriving at the victim: 1 Gbit/s × 50 = 50 Gbit/s.',
   'Uplink headroom: 50 ÷ 10 = 5 times over capacity.',
   'Even with filters on the servers, 40 Gbit/s of the flood is dropped at random before reaching them, real traffic included.'],
  'The site cannot defend itself behind its own uplink; the attack must be absorbed upstream by an edge or scrubbing provider.',
  'SYN flooding and ingress filtering in the RFCs, and AWS guidance', 'Official documentation',
  'RFC 4987 surveys SYN flooding attacks and mitigations, including SYN caches and SYN cookies, and explains their trade-offs. RFC 2827, also known as BCP 38, asks network operators to drop packets whose source addresses could not have come from the customer network that sent them, which blocks spoofing and therefore reflection. The AWS whitepaper on DDoS resiliency recommends reducing the attack surface, absorbing volumetric attacks at edge locations and scaling to absorb application-layer floods while protecting the origin.',
  [('“We’ll block the attacking IPs.”', '“The sources are forged or innocent reflectors, so I’d filter by protocol and absorb upstream instead.”'),
   ('“Autoscaling handles DDoS.”', '“It helps with request floods for a while, but a volumetric attack fills the link first, and unlimited scaling becomes a bill.”')],
  ['Volumetric floods fill links, protocol floods exhaust state, application floods exhaust work.', 'SYN cookies let a server keep no state until the handshake completes.', 'Amplification = reply size ÷ request size; spoofing makes reflection possible.', 'Absorb floods upstream and let the origin accept traffic only from the edge.']),
 predict('Attackers found your origin',
  'Your site sits behind a CDN, but a flood now hits the origin servers’ public address directly, bypassing the CDN. What do you do first?',
  [('a', 'Add more origin servers to absorb the traffic', 'More servers behind the same link do not help once that link is full, and they cost money during the attack.'),
   ('b', 'Accept only the CDN’s address ranges, then move the origin', 'Right: with the origin closed to everyone but the edge, direct floods are dropped upstream, and a new address the attackers do not know ends the bypass.'),
   ('c', 'Lower the DNS TTL on the site’s main record', 'The attackers already have the origin’s address; DNS changes do not stop traffic aimed straight at it.')],
  'b', 'An origin behind an edge should accept traffic only from that edge, ideally through a private connection or firewall rules at the network level, and its address should not leak through old DNS records, mail headers or certificates. Then volumetric attacks land on the edge, which has the capacity to absorb them.'),
 see([(41, 'Rate limiting algorithms behind per-client limits for request floods'), (19, 'CDN edges absorb floods and hide the origin'), (328, 'Autoscaling helps briefly with request floods but needs limits')])))

# ---------------------------------------------------------------- 548 Nagle and delayed ACKs
T.append(topic(548, 'nagle-and-delayed-acks', R, 22, 'Nagle’s Algorithm and Delayed ACKs',
 ['Explain what Nagle’s algorithm and delayed ACKs each save',
  'Diagnose the stall when a sender writes a request in two pieces',
  'Choose between combining writes and disabling Nagle'],
 3, 10, [247],
 [text(548, 1, 'Two good ideas that collide',
   'Nagle’s algorithm (RFC 896) stops a sender from flooding the network with tiny packets: while any sent data is unacknowledged, small writes are held until an ACK arrives or a full segment builds up. A delayed ACK (RFC 1122) lets a receiver wait briefly, hoping to carry the ACK on its own reply; it must still ACK at least every second full-sized segment and within 500 ms. Each saves packets. Together they can deadlock briefly.',
   ['nagle', 'delayed-ack']),
  worked(548, 2, 'Worked example: the 40 ms stall in write-write-read',
   'A client sends a request as a header write followed by a body write, then waits for the reply.', ['write-write-read'],
   ['The header (200 bytes) goes out at once, since nothing is unacknowledged',
    'The body (300 bytes) is held by Nagle, because the header is not yet ACKed',
    'The server cannot reply without the body, so it has nothing to carry an ACK and delays it',
    'The delayed-ACK timer fires: 40 ms is a common Linux minimum, and some systems wait 200 ms',
    'The ACK frees the body, the server replies, and the request finishes about 40 ms late'],
   'Result. In a data centre with a 0.5 ms round trip, a call that should take about 1 ms takes about 41 ms, roughly 40 times slower, and the delay does not depend on payload size.'),
  text(548, 3, 'Fix the write pattern first',
   'The cleanest fix is to send each message in one write: build the header and body in one buffer, or use a gather write that hands the kernel several buffers at once. Request and response protocols, such as most RPC and database clients, also set TCP_NODELAY to turn Nagle off, since they care about latency per message. With Nagle off, many tiny writes do become many tiny packets, so buffer in the application.',
   ['tcp-nodelay']),
  text(548, 4, 'Misconception: delayed ACKs are the bug',
   'Each feature helps on its own: delayed ACKs roughly halve ACK traffic on bulk transfers, and Nagle protects slow links from one-byte packets. The stall comes from the pattern, a sender that waits for an ACK the receiver will not send until it has more data. Remove the pattern with one write per message, or turn Nagle off for that socket; turning off delayed ACKs everywhere costs more and is not portable.',
   ['delayed-ack', 'nagle']),
  text(548, 5, 'Trap: benchmarks that only ever send one write',
   'A test that sends each request in a single write never sees the stall, so it passes, while production code with a separate header write is slow. The tell is latency stuck near 40 ms or 200 ms whatever the payload size, and in a packet capture, a gap of exactly that length before the second segment. Test with the real client library and the real message pattern.',
   ['write-write-read'])],
 [mc('t548-a1', 'nagle', 'What does Nagle’s algorithm do?',
   [('a', 'Delays ACKs so they can ride on replies'), ('b', 'Splits large writes into MSS-sized segments'), ('c', 'Holds small writes while sent data is unACKed'), ('d', 'Resends lost segments sooner than the timer')], 'c',
   'Nagle batches small writes on the sender. Delaying ACKs is the receiver-side feature; splitting into segments happens anyway; and early resends are fast retransmit, a different mechanism.'),
  mc('t548-a2', 'delayed-ack', 'Why does a receiver delay its ACKs?',
   [('a', 'To send fewer ACKs, often carried on its reply'), ('b', 'To slow down a sender that is too fast'), ('c', 'To wait for the sender to send its FIN'), ('d', 'To give the congestion window time to grow')], 'a',
   'Combining the ACK with a reply saves packets. Slowing a sender is the receive window’s job; the FIN is unrelated; and the sender’s window grows on ACKs, so delaying them slows growth.'),
  mc('t548-a3', 'write-write-read', 'Requests inside a data centre (0.5 ms round trip) take a flat 40 ms. The client writes the header and the body separately. What is the likely cause?',
   [('a', 'The server’s thread pool is too small'), ('b', 'Nagle holds the body while the server delays its ACK'), ('c', 'Each request sets up a new TLS session'), ('d', 'The switches in the path add 40 ms of queueing delay')], 'b',
   'A flat delay matching the delayed-ACK timer, with split writes, is the classic sign. A small thread pool gives delays that grow with load; a TLS setup costs round trips, about 1 ms here; and switch queueing is microseconds to a few ms.'),
  mc('t548-a4', 'tcp-nodelay', 'Which fix removes the stall without filling the network with tiny packets?',
   [('a', 'Turn off delayed ACKs on every server'), ('b', 'Set TCP_NODELAY and keep writing byte by byte'), ('c', 'Increase the receive window on the server'), ('d', 'Send the header and body in one write')], 'd',
   'One write per message gives Nagle nothing to hold. Disabling delayed ACKs everywhere is costly and not portable; TCP_NODELAY with byte-sized writes sends a packet per byte; and the window is not the limit.'),
  mc('t548-a5', 'nagle', 'Which workload actually benefits from Nagle’s algorithm?',
   [('a', 'An RPC service exchanging small requests and replies'), ('b', 'A multiplayer game sending a position update every 16 ms'), ('c', 'A remote terminal over a slow link, one key per write'), ('d', 'A database client sending short queries')], 'c',
   'Batching keystrokes saves many 41-byte packets on a slow link. RPC calls, game updates and database queries are latency-sensitive messages that should go out at once, which is why their clients usually set TCP_NODELAY.'),
  order('t548-a6', 'write-write-read', 'Order the events in the write-write-read stall.',
   ['The client sends the header immediately', 'Nagle holds the body until the header is ACKed', 'The server delays its ACK while waiting for the body', 'The delayed-ACK timer fires and the ACK is sent', 'The body goes out and the server replies'],
   ['s3', 's1', 's5', 's2', 's4'], 'Each side waits for the other until the receiver’s timer breaks the tie.'),
  est('t548-a7', 'nagle', 'A 1-byte keystroke goes in its own IPv4 packet with a 20-byte IP header and a 20-byte TCP header. What percentage of the bytes is payload?', '%', 2.4,
   ['No TCP options', 'Link-layer framing ignored'],
   '1 ÷ (1 + 20 + 20) × 100', '1 ÷ 41 × 100 ≈ 2.4%',
   'Sanity check: about 98% of such a packet is header, which is the waste Nagle was designed to cut on slow links.', 0.05, [4.8, 1, 5])],
 flash(548, [('Nagle’s algorithm?', 'Hold small writes while sent data is unacknowledged.'),
             ('Delayed ACK?', 'The receiver waits briefly to carry its ACK on a reply; at least every second full segment, under 500 ms.'),
             ('Write-write-read fix?', 'One write per message, or TCP_NODELAY on latency-sensitive sockets.')]),
 src([('RFC 896: Congestion Control in IP/TCP Internetworks', 'https://www.rfc-editor.org/rfc/rfc896'),
      ('RFC 1122: Requirements for Internet Hosts, section 4.2.3.2', 'https://www.rfc-editor.org/rfc/rfc1122#section-4.2.3.2'),
      ('man7: tcp(7)', 'https://man7.org/linux/man-pages/man7/tcp.7.html')]),
 deep(['nagle', 'delayed-ack', 'write-write-read'], 'How two packet savers create a pause',
  ['A TCP sender can send data as soon as the application writes it. On a slow, shared link in the 1980s, terminals sending one keystroke per packet spent about 40 bytes of headers on every byte typed. John Nagle’s rule, RFC 896, fixed that: if any data is in flight and unacknowledged, hold new small writes and send them together when the ACK arrives or a full segment is ready.',
   'Receivers made a matching optimisation. Instead of acknowledging every segment at once, a receiver may wait a short time, because the application will often reply and the ACK can ride on that reply for free. RFC 1122 bounds the wait at 500 ms and requires an ACK for at least every second full-sized segment, so bulk transfers are acknowledged promptly.',
   'The two collide when a sender writes a message in two parts and then waits for a reply. The first part goes out immediately. The second is small and data is unacknowledged, so Nagle holds it. The receiver has only part of the message, so it has no reply to send and delays its ACK. Neither side moves until the receiver’s delayed-ACK timer fires.',
   'The timer length sets the penalty. Linux commonly uses a minimum of 40 ms, adjusting with observed round trips; other systems have used 200 ms. In a data centre with sub-millisecond round trips, the timer is many times longer than the request itself, so a service can be dozens of times slower than it should be with no sign of load.',
   'There are two clean fixes. Write each message in a single call so there is never a held second part, which also saves system calls. Or set TCP_NODELAY on the socket so small writes go out at once, which most request and response libraries do; then the application should batch its own writes to avoid sending many tiny packets.'],
  ['Diagnosing latency stuck near 40 ms or 200 ms for small requests.', 'Choosing socket options for RPC, database or game protocols.'],
  ['Avoid turning off delayed ACKs system-wide as the fix.', 'Avoid TCP_NODELAY combined with many tiny writes per message.'],
  ['Setting', 'Small-write latency', 'Packets on the wire'],
  [['Nagle on, one write per message', 'Low', 'Few, full packets'],
   ['Nagle on, split writes', 'Up to the delayed-ACK timer', 'Few, but late'],
   ['Nagle off (TCP_NODELAY), app buffering', 'Low', 'One per message'],
   ['Nagle off, byte-by-byte writes', 'Low', 'Very many tiny packets']],
  'The price of a split write',
  ['Round-trip time 0.5 ms, server work 0.5 ms', 'Delayed-ACK timer 40 ms', 'Client writes header and body separately'],
  ['Expected latency with one write: 0.5 ms RTT + 0.5 ms work = 1 ms.',
   'With a split write the body waits for the delayed ACK: + 40 ms.',
   'Actual latency ≈ 41 ms, about 41 times the expected 1 ms.',
   'A client doing 100 such calls one after another spends 4.1 s instead of 0.1 s.'],
  'A pattern bug, not load, multiplies latency forty-fold; one write per message removes it.',
  'Nagle and delayed ACKs in the RFCs and the Linux manual', 'Official documentation',
  'RFC 896, written by John Nagle in 1984, describes the small-packet problem and the rule of holding new data while earlier data is unacknowledged. RFC 1122 section 4.2.3.2 lets hosts delay ACKs, but requires an ACK for at least every second full-sized segment and a delay under 0.5 seconds. The Linux tcp(7) manual page documents TCP_NODELAY, which disables Nagle on a socket, and TCP_QUICKACK, which only temporarily leaves delayed-ACK mode.',
  [('“The network adds 40 ms.”', '“A flat 40 ms with split writes is Nagle meeting a delayed ACK; I’d send one write per message.”'),
   ('“Just disable delayed ACKs everywhere.”', '“The pattern is the problem; one write per message or TCP_NODELAY on that socket fixes it without changing every host.”')],
  ['Nagle holds small writes while data is unacknowledged; delayed ACKs wait to ride on replies.', 'Write-write-read stalls until the delayed-ACK timer, often 40 ms or 200 ms.', 'Send each message in one write, or set TCP_NODELAY and buffer in the app.', 'Latency flat near the ACK timer regardless of size is the tell.']),
 predict('Guess the latency',
  'A client in the same data centre as its server (0.5 ms round trip) sends each request as two writes, a header then a body, and waits for the reply. Nagle is on, and the server delays ACKs with a 40 ms timer. The server needs 0.5 ms per request. What latency do you expect?',
  [('a', 'About 1 ms', 'That is the latency with one write per message. Here the body waits for an ACK the server is holding back.'),
   ('b', 'About 41 ms', 'Right: Nagle holds the body until the header is acknowledged, and the server holds the ACK until its 40 ms timer fires.'),
   ('c', 'About 80 ms', 'The timer fires once per request: after it the body goes out and the reply follows within about a millisecond.')],
  'b', 'Each side waits on the other until the delayed-ACK timer breaks the tie, so the request costs the timer plus the normal 1 ms. Combine the writes or set TCP_NODELAY, and latency drops back to about 1 ms.'),
 see([(247, 'TCP acknowledgements and segments, which both features change'), (9, 'RPC frameworks that set TCP_NODELAY for low-latency calls'), (253, 'Why latency, not bandwidth, dominates small request and reply messages')])))


